/**
 * Questions people ask about a component, shown on its page and sent to search engines as
 * FAQPage structured data. Every answer has to be true of the shipped component.
 */
export type ComponentFaqItem = { q: string; a: string };

export const COMPONENT_FAQ: Record<string, ComponentFaqItem[]> = {
  "animated-countdown": [
    { q: "How do I set the date it counts down to?", a: "Pass `targetDate` as a Date, an ISO string or a timestamp. Without a target it shows a static demo time, which you can set with `initialStaticTime`." },
    { q: "What styles are available?", a: "`variant` can be \"modern\", \"digital\", \"minimal\" or \"classic\", and `size` can be \"sm\", \"md\" or \"lg\". Separators between units are on by default for the digital style." },
    { q: "Can I run code when the timer reaches zero?", a: "Yes. `onComplete` is called once when the countdown finishes, and `completionMessage` shows a line of text under the timer." },
    { q: "Can I hide days or seconds?", a: "Use `showDays`, `showHours`, `showMinutes` and `showSeconds`, and `unitOrder` to change the order. With reduced motion enabled, digits swap with a quick fade instead of sliding." },
  ],
  "animated-select-headline": [
    { q: "How do I change the rotating words?", a: "Pass `words` as an array of strings, plus `prefix` and `suffix` for the fixed text around them." },
    { q: "How fast do the words change?", a: "Set `interval` in milliseconds; the default is 2500." },
    { q: "Can I change the gradient colors?", a: "The last two words use the gradients in the `ACCENT_GRADIENTS` array at the top of the file (cyan to emerald, amber to pink). Edit those Tailwind classes to change them." },
    { q: "Does it support dark mode?", a: "The heading uses dark text by default. Pass `headingClassName=\"dark:text-white\"`, as the demo does, to switch it in dark mode." },
  ],
  "ask-nexus-input": [
    { q: "How do I install the Ask Nexus input?", a: "Run `npx shadcn@latest add @nexus-labs/ask-nexus-input`. It installs framer-motion and lucide-react; the dust effect needs no other library." },
    { q: "How do I get the submitted query?", a: "Pass `onSubmit`. It fires with the trimmed value the moment the user submits, before the animation starts. If the input is empty, the placeholder currently showing is submitted instead." },
    { q: "How do I change the headline and suggestions?", a: "Use `title` for the headline, `placeholders` for the rotating suggestions, and `placeholderInterval` (default 2800 ms) for how often they change." },
    { q: "How is the disintegration effect made?", a: "The submitted text is drawn onto a 2D canvas and broken into particles that peel away from right to left, animated with requestAnimationFrame. There is no WebGL." },
  ],
  "avatar-group": [
    { q: "How do I install the avatar group?", a: "Run `npx shadcn@latest add @nexus-labs/avatar-group`. It adds the AvatarGroup component and installs framer-motion." },
    { q: "What data does each avatar take?", a: "Pass `avatars` as `{ src?, alt?, fallback, tooltip?, bgColor? }`. Without an image, or if the image fails to load, the `fallback` initials show on a colored circle, and `tooltip` sets the name shown on hover." },
    { q: "Which animations can I choose?", a: "`entranceAnimation` takes \"none\", \"fade\", \"flip\", \"slide\", \"scale\" or \"bounce\", staggered by `entranceStagger`. `hoverAnimation` takes \"scale\", \"lift\", \"rotate\", \"up\" or \"none\", with `hoverScale` for the zoom." },
    { q: "How do I adjust size and spacing?", a: "`size` sets the diameter in px (default 40), `overlap` sets how far avatars overlap (default 10), and `borderWidth`/`borderColor` style the ring. With reduced motion on, the entrance and hover animations are turned off." },
  ],
  "beam-sweep-field": [
    { q: "How do I install Beam Sweep Field?", a: "Run `npx shadcn@latest add @nexus-labs/beam-sweep-field`. It installs framer-motion and lucide-react." },
    { q: "Which props control the beams?", a: "`beams` sets how many light columns sweep (default 3), `color` sets their color (default `#67e8f9`), and `speed` sets the seconds per sweep (default 11)." },
    { q: "How do I put my own content on it?", a: "Pass anything as `children` and it replaces the built-in sample hero. Use `className` to change the section's height or corner radius." },
    { q: "Does it use canvas or WebGL?", a: "No. The grid and glow are CSS gradients and each beam is a Framer Motion div. With prefers-reduced-motion on, the beams stay still." },
  ],
  "card-stack-rotator": [
    { q: "How do I highlight words in a quote?", a: "Wrap the words in double asterisks, like `**absolutely incredible**`, inside a card's `content`. They render as a highlighted mark." },
    { q: "How do I change the rotation speed?", a: "Set `rotationInterval` in milliseconds (default 3000). `pauseOnHover` is on by default, and `maxVisible`, `stackOffset` and `scaleStep` shape the stack." },
    { q: "What does each card need?", a: "Each card takes `id`, `content`, `name` and `designation`, plus optional `avatarUrl`, `initials` and `company`. Without an avatar, initials are generated from the name." },
    { q: "How do I add it to my project?", a: "Copy the component source from this page into your project and install framer-motion. Auto-rotation stops for users who prefer reduced motion." },
  ],
  "chat-messages": [
    { q: "How do I install the Chat Messages component?", a: "Run `npx shadcn@latest add @nexus-labs/chat-messages`. It adds chat-messages.tsx to your project and uses framer-motion and lucide-react." },
    { q: "How do I show my own conversation?", a: "Pass a `messages` array of `{ id, sender: \"user\" | \"assistant\", content }` objects. Assistant messages show the typing dots for `typingDuration` ms before they appear, and `autoPlayDelay` sets the gap between messages." },
    { q: "Can visitors type into the chat?", a: "Set `interactive` to true to enable the input; Enter sends the message. The reply is a fixed placeholder, so connect the send handler to your own API for a real chatbot. By default it runs as a demo with a replay button (`showReplay`)." },
    { q: "Does it work with the Next.js App Router?", a: "Yes. The file starts with \"use client\", so you can render it from a server page. The message list uses role=\"log\" with aria-live so screen readers announce new messages." },
  ],
  "cinematic-card-deck": [
    { q: "How does the scroll effect work?", a: "The section is `sectionHeight` vh tall (default 400) with a sticky viewport inside it, and scroll progress through the section decides which card is in front. `smoothing` controls how softly the cards follow the scroll." },
    { q: "Can I use it inside a scrollable container?", a: "Yes. Pass the container as `scrollContainerRef` and set `viewportHeight` to match its height." },
    { q: "How do I add my own cards?", a: "Pass `cards` as an array of `{ title, description, tag, cardColor, accentColor, imageUrl }`; everything except title and description is optional." },
    { q: "How do I make the effect stronger or calmer?", a: "Set `intensity` to \"subtle\", \"standard\" or \"cinematic\" and `exitDirection` to \"up\" or \"down\". `showProgress`, `showAmbientGlow` and `glowIntensity` control the extras." },
  ],
  "cinematic-logo-cloud": [
    { q: "How do I switch between grid and marquee?", a: "Set `variant` to \"grid\" (the default, with a staggered blur-fade when it scrolls into view), \"marquee\" for logos only, or \"marquee-named\" for a small logo plus the brand name." },
    { q: "Where do the logos come from?", a: "Each client's `slug` loads an icon from cdn.simpleicons.org. Set `text: true` to show the name as text instead, and `invertDark` to invert dark logos in dark mode." },
    { q: "How do I install it?", a: "Run `npx shadcn@latest add @nexus-labs/cinematic-logo-cloud`. It adds the logo cloud and a small Marquee helper, and depends only on framer-motion." },
    { q: "Can I change the heading text?", a: "Yes. Use the `eyebrow` prop for the small heading and `description` for the line under it in the grid layout." },
  ],
  "circular-carousel": [
    { q: "What data does the carousel need?", a: "Pass `items` as an array of `{ id, title, description, tag? }`. Up to five cards are shown on the arc, and the center shows the active number out of the total." },
    { q: "How does autoplay work?", a: "`autoPlay` is on by default and advances every `autoPlayInterval` ms (default 4000). It pauses while the carousel is hovered or focused." },
    { q: "Can I control the active slide from outside?", a: "Yes. Pass `activeIndex` and handle `onActiveChange` to make it a controlled component." },
    { q: "Is it keyboard accessible?", a: "The carousel is focusable and responds to the Left and Right arrow keys. The previous and next buttons and the dot indicators have aria-labels." },
  ],
  "code-block": [
    { q: "How do I add the code block to my project?", a: "Copy the CodeBlock source from the Code tab into your project. It is a single client component whose only dependency is framer-motion." },
    { q: "Which languages does it highlight?", a: "Its built-in tokenizer handles `js`, `ts`, `jsx`, `tsx`, `css`, `json` and `html`, plus `plain` for no highlighting. Set the language with the `language` prop (default \"jsx\")." },
    { q: "How do I customize its look?", a: "`theme` takes \"dark\", \"light\" or \"custom\". The `header` prop controls the title, window dots and copy button, `codeArea` controls line numbers, wrapping, padding and colors, and `border` sets color, width and radius." },
    { q: "How does the copy button work?", a: "It uses the Clipboard API, falling back to a hidden textarea in older browsers. The label switches to the copied label for `header.copy.copiedDurationMs` (default 1200 ms)." },
  ],
  "command-palette": [
    { q: "How do I install the command palette?", a: "Run `npx shadcn@latest add @nexus-labs/command-palette`. It installs cmdk, @radix-ui/react-dialog, framer-motion and lucide-react, plus the shadcn/ui command component." },
    { q: "Which keyboard shortcuts does it support?", a: "Cmd+K on macOS or Ctrl+K elsewhere toggles it, the arrow keys move through results, Enter selects, and Esc closes. The search input is focused when it opens." },
    { q: "How do I change the commands?", a: "The commands live in the `COMMANDS` array at the top of the file, each with a label, description, Lucide icon, action hint and value. Selecting an item closes the palette, so add your own navigation or action logic in the item's `onSelect` handler." },
    { q: "Does it work with the Next.js App Router?", a: "Yes. It is a client component (`\"use client\"`) that listens for the shortcut on `window`, so render it from any page or layout." },
  ],
  "compare": [
    { q: "How do I install the compare slider?", a: "Run `npx shadcn@latest add @nexus-labs/compare`. Its only dependency is lucide-react for the handle icon; there is no animation library." },
    { q: "How does the divider move?", a: "On desktop the divider follows the mouse across the image and returns to `initialPosition` (default 50) when the cursor leaves. On touch screens you drag with a finger." },
    { q: "Can I compare something other than two images?", a: "Yes. `beforeContent` and `afterContent` accept any React node and take priority over `beforeImage` and `afterImage`, so you can compare two UI states, code renders or designs." },
    { q: "How do I set the size and labels?", a: "Set the height or aspect ratio through `className` (for example `aspect-video`). `beforeLabel` and `afterLabel` add small pills in the top corners." },
  ],
  "depth-testimonials": [
    { q: "How do I install Depth Testimonials?", a: "Run `npx shadcn@latest add @nexus-labs/depth-testimonials`. It installs framer-motion and lucide-react." },
    { q: "How do I add my testimonials?", a: "Pass `items` as `{ quote, name, role?, tone? }`, where `tone` is an optional pair of colors. A plain `quotes` string array also works, and `heading` sets the section title." },
    { q: "Can I change or turn off autoplay?", a: "`interval` sets the auto-advance time in milliseconds (default 4800), and 0 turns it off. It pauses while the pointer is over the section and does not autoplay when reduced motion is on." },
    { q: "Can users navigate it themselves?", a: "Yes. Previous and next buttons and a row of dot buttons, each with an accessible label, let users move through the quotes. It also supports dark mode through Tailwind `dark:` classes." },
  ],
  "dot-grid-hero": [
    { q: "Which props change the particle physics?", a: "`dotGap` (default 72px) sets the spacing, `interactionRadius` (120px) and `repulsionStrength` (7) set how far and hard particles are pushed, and `springK` and `damping` control how they settle back." },
    { q: "Can I change the colors?", a: "Yes. Pass `colors` as an array of hex values for the particles, plus `background` and `textColor` for the hero itself." },
    { q: "How do I edit the headline and buttons?", a: "Use `title` (with \n for a line break), `subtitle`, and `primaryCTA` / `secondaryCTA` as `{ label, href, onClick }`." },
    { q: "Is it heavy on performance?", a: "The canvas loop pauses when the hero is off screen or the tab is hidden, and the cursor push is turned off for users who prefer reduced motion." },
  ],
  "draggable-card-stack": [
    { q: "How far do I need to drag a card?", a: "The top card goes to the back once it is dragged more than 120px or flung faster than 400px/s. Shorter drags spring back to the center." },
    { q: "Can I control the stack with the keyboard?", a: "Yes. ArrowRight or Space sends the top card to the back and ArrowLeft brings the last card to the front. The listener is on the window, so those keys work anywhere on the page while the stack is mounted." },
    { q: "Does it support videos?", a: "Set `type: \"video\"` on a card and pass the video URL as `media`. Videos are muted and looped, and only the top card plays." },
    { q: "Can the cards cycle on their own?", a: "Turn on `autoPlay` and set `autoInterval` in milliseconds (default 3000). Other props such as `cardWidth`, `cardHeight`, `maxRotation` and `showOverlay` control the look." },
  ],
  "editorial-blog-rail": [
    { q: "How do I pass my posts?", a: "Pass `featured` as one post and `posts` as an array. Each post has `title`, `category`, `date`, `readTime` and `href`; the featured post can also take `excerpt` and `author`." },
    { q: "Do I need cover images?", a: "No. The featured cover is drawn from two colors you pass as `cover: [from, to]`, and the author avatar shows their initials." },
    { q: "How do I change the heading and the View all link?", a: "Use the `heading` and `allHref` props." },
    { q: "How do I install it?", a: "Run `npx shadcn@latest add @nexus-labs/editorial-blog-rail` and import `EditorialRail`. Entrance animations are skipped for users who prefer reduced motion." },
  ],
  "glowing-effect-cards": [
    { q: "Can I put the glow around my own content?", a: "Yes. Wrap any content in `GlowingEffect`. `GlowingCard` is a ready-made card with title, description, icon and CTA, and `GlowingCardsLayout` is the 2-1-2 grid from the demo." },
    { q: "Which props control the glow?", a: "`intensity` (clamped between 0.45 and 2.4) scales the glow, `blur` softens it, `borderRadius` matches your card shape and `disabled` turns it off. The three glow colors are set inside GlowingEffect.tsx, so edit them there to match your brand." },
    { q: "Does it work with the keyboard?", a: "Each card is focusable and lights up on focus. For users who prefer reduced motion, the glow no longer tracks the pointer." },
    { q: "How do I install it?", a: "Run `npx shadcn@latest add @nexus-labs/glowing-effect-cards`. It comes with Pro and uses framer-motion and lucide-react." },
  ],
  "gooey-search-input": [
    { q: "How do I install the gooey search input?", a: "Run `npx shadcn@latest add @nexus-labs/gooey-input`. Note that the registry name is `gooey-input`, not the page slug. It installs framer-motion and lucide-react." },
    { q: "Can I use it as a controlled input?", a: "Yes. Pass `value` with `onValueChange`, or use `defaultValue` for uncontrolled mode. `onOpenChange` tells you when it expands or collapses." },
    { q: "When does it collapse again?", a: "It collapses on blur when the field is empty, and Esc blurs it. The text is cleared when it collapses." },
    { q: "How do I change its size and the goo strength?", a: "`collapsedWidth` (115), `expandedWidth` (200) and `expandedOffset` (56) are in pixels, and `gooeyBlur` (5) sets the SVG blur that merges the shapes. It shows a dark pill in light mode and a white pill in dark mode." },
  ],
  "hover-highlight-text": [
    { q: "Which props control the highlight?", a: "`spotlightRadius` (default 118px) and `spotlightSoftness` set the size and edge, `strokeColor` and `strokeWidth` style the outline, and `springConfig` changes how the spotlight follows the cursor. `enableGlow` adds a faint glow." },
    { q: "Can I use it for an h1?", a: "Yes. Set `as` to \"h1\", \"h2\", \"p\" or \"span\" (default h2). The outlined copy is aria-hidden, so screen readers read the text once." },
    { q: "Does it work on touch devices?", a: "Yes. Tapping reveals the highlight at the touch point." },
    { q: "What happens with reduced motion?", a: "The spotlight no longer follows the pointer; the outlined layer is shown at low opacity instead." },
  ],
  "image-trail": [
    { q: "How do I use my own images?", a: "Pass `images` as an array of `{ src, alt }`; they are used in order as the cursor moves. Anything you pass as `children` renders above the trail." },
    { q: "Which props control the trail?", a: "`spacing` (default 40px) sets how far the cursor travels before a new image appears, `duration` (default 1000ms) how long each stays, and `imageSize`, `cornerRadius`, `fadeInBlur` and `fadeOutBlur` the look. They also work grouped as `trailSettings`, `appearance` and `animation`." },
    { q: "Does the cursor image trail work on mobile?", a: "Yes, it listens to touch moves as well as the mouse. For users who prefer reduced motion, images appear and disappear with a short fade instead of the scale and blur animation." },
    { q: "How do I install it?", a: "Run `npx shadcn@latest add @nexus-labs/image-trail`. Set `magneticEffect` to make trail images drift toward the cursor." },
  ],
  "images-badge": [
    { q: "How do I install the images badge?", a: "Run `npx shadcn@latest add @nexus-labs/images-badge`. It adds the ImagesBadge component and installs framer-motion." },
    { q: "How many images does it show?", a: "`maxVisible` (default 3) sets how many are visible when collapsed and `revealCount` (default 2) how many more appear on hover. Any images beyond that are summarized in a \"+N\" chip." },
    { q: "Can the badge be clickable?", a: "Yes. Pass `onClick` and the badge gets a button role, becomes focusable, and responds to Enter and Space." },
    { q: "Which sizes and shapes are available?", a: "`size` takes \"sm\", \"md\" or \"lg\" and `shape` takes \"circle\", \"rounded\" or \"square\". `label` adds text after the stack, and dark mode is handled with Tailwind `dark:` classes." },
  ],
  "infinite-moving-cards": [
    { q: "How do I change the speed and direction?", a: "Set `speed` to \"slow\", \"normal\" or \"fast\" (about 26, 44 or 74 px per second) and `direction` to \"left\" or \"right\". `pauseOnHover` is on by default." },
    { q: "Can I render my own card design?", a: "Yes. Pass `renderItem={(item, index) => ...}` to replace the default card. Without it, each card can show an image, title, description, star rating, tags and an avatar with name and role." },
    { q: "What happens for users who prefer reduced motion?", a: "The track stops scrolling and the cards are shown in place." },
    { q: "How do I install it?", a: "Run `npx shadcn@latest add @nexus-labs/infinite-moving-cards`. It comes with Pro and only needs framer-motion; `showGradientMask` controls the faded edges." },
  ],
  "interactive-globe-explorer": [
    { q: "How do I install the globe explorer?", a: "Run `npx shadcn@latest add @nexus-labs/interactive-globe-explorer`. It installs react-globe.gl, three and lucide-react along with the shadcn/ui button." },
    { q: "How do I show my own office locations?", a: "Pass a `locations` array of `{ id, name, lat, lng, address, email }` objects; without it the component shows 20 sample offices. `initialLocationId` picks the city the globe focuses on first." },
    { q: "Does it work with the Next.js App Router?", a: "Yes. It is a client component and loads react-globe.gl through `next/dynamic` with `ssr: false`, so the WebGL globe only renders in the browser. Because it imports `next/dynamic`, it is built for Next.js projects." },
    { q: "Where does the earth texture come from?", a: "The `globeTextureUrl` prop sets it, defaulting to `/images/earth-blue-marble.jpg`. Put an earth texture at that path in your public folder or point the prop at your own image." },
  ],
  "mac-keyboard": [
    { q: "How do I install the Mac keyboard?", a: "Run `npx shadcn@latest add @nexus-labs/mac-keyboard`. It installs framer-motion. For the recorded key clicks, copy `keys.ogg` (about 200 KB) into `public/sounds/`; without it the keys use a click synthesised with the Web Audio API, so nothing breaks." },
    { q: "How do I highlight keys as the user types?", a: "Call the exported `usePhysicalKeyboard()` hook and pass its result to `activeKeys`. Keys matching the pressed `KeyboardEvent.code` values show as held down." },
    { q: "Which sound options are there?", a: "`enableSound` turns sound on or off, `soundType` picks \"mechanical\", \"soft\" or \"clicky\", and `volume` goes from 0 to 1. Sounds play when virtual keys are clicked, and `onKeyPress` gives you the key that was pressed." },
    { q: "Can I change the layout and theme?", a: "`layout` is \"mac\" or \"compact\", `showFunctionRow` hides the Esc and F-key row, and `theme` is \"dark\", \"light\" or \"auto\", which follows the `dark` class on the html element." },
  ],
  "meteors": [
    { q: "How do I install the Meteor Effect?", a: "Run `npx shadcn@latest add @nexus-labs/meteors`. It adds the Meteors component to your project and installs framer-motion, its only animation dependency." },
    { q: "How do I change how many meteors appear and which way they fall?", a: "Use `number` (default 18) together with `intensity` (\"low\", \"medium\" or \"high\", which scale the count to 0.65x, 1x or 1.45x, capped at 72). `angle` sets the travel direction in degrees (default 215), and `minDuration`/`maxDuration` and `minDelay`/`maxDelay` control speed and spacing." },
    { q: "Can the meteors only animate on hover?", a: "Yes. Set `hoverOnly` and the meteors only show while the pointer is over the container. Anything you pass as `children` renders above the meteor layer, so you can wrap a card or hero with it." },
    { q: "Does it respect reduced motion?", a: "Yes. When the user has prefers-reduced-motion turned on, the meteors stay in place as faint static streaks instead of moving." },
  ],
  "milestone-timeline": [
    { q: "How do I add my own milestones?", a: "Pass `milestones` as an array of `{ title, date, description, status, tag }`, where status is \"done\", \"current\" or \"upcoming\". For a quick list you can pass `steps` as plain strings instead; every step before the last is treated as done." },
    { q: "Is this an alternative to the Material UI Timeline?", a: "It covers the same vertical timeline layout without MUI: it is a single Tailwind CSS component that only depends on framer-motion and lucide-react." },
    { q: "Does it support dark mode and reduced motion?", a: "Yes. It ships with Tailwind `dark:` styles, and when the user prefers reduced motion the entrance animation and the pulsing ring on the current milestone are skipped." },
    { q: "How does it look on mobile?", a: "Below the `sm` breakpoint the date column is hidden and each date moves inline next to its milestone title, so the timeline stays readable on narrow screens." },
  ],
  "nebula-cta-glow": [
    { q: "How do I install it?", a: "Run `npx shadcn@latest add @nexus-labs/nebula-cta-glow`. It exports a `NebulaCta` component and only depends on framer-motion." },
    { q: "How do I change the button text or link?", a: "The component has no props, so edit the button label in the JSX. To link somewhere, swap the button for an anchor or your router's Link." },
    { q: "How do I change the glow color or speed?", a: "The glow is a blurred circle with the `bg-cyan-400/25` class; change that class for a new color and the 4-second `duration` for a faster or slower pulse." },
    { q: "Does it work with the Next.js App Router?", a: "Yes. The file is marked \"use client\", so you can drop it into a server-rendered page." },
  ],
  "orbit-footer": [
    { q: "How do I change the footer links?", a: "Pass `columns` as an array of `{ title, links: [{ label, href, badge? }] }`. The Privacy, Terms and social links are written in the component file, so edit them there." },
    { q: "How do I connect the newsletter form?", a: "Pass `onSubscribe(email)`. If it returns a promise, the button shows a pending state until it resolves. Set `showNewsletter` to false to hide the form." },
    { q: "Can I remove the status pill or the big wordmark?", a: "Set `status` to null to hide the status pill, or change its text and `statusHref`. Set `showWordmark` to false to remove the large ghost wordmark; `brand` sets the name used in both places." },
    { q: "Is the footer free to use?", a: "Yes, it is a free component. Install it with `npx shadcn@latest add @nexus-labs/orbit-footer`." },
  ],
  "orbital-loader": [
    { q: "Can it show real progress instead of spinning?", a: "Yes. Pass `progress` as a number from 0 to 1 and the arc fills to that value with a percentage in the middle. Leave it out for an endless sweeping arc." },
    { q: "How do I change the loading messages?", a: "Pass `messages` as an array of strings; they rotate every 1.8 seconds. Pass a single string for a fixed label, or an empty array to hide the text." },
    { q: "How do I change the size and color?", a: "`size` sets the diameter in pixels (default 112) and `color` sets the arc and orbiting dot color (default #6366f1)." },
    { q: "Is the orb loader accessible?", a: "It renders with role=\"status\" and aria-live=\"polite\", so the status text is announced, and the spinning stops when the user prefers reduced motion. It also has dark mode styles." },
  ],
  "phone-input": [
    { q: "How do I read the entered number?", a: "Pass `onChange`; it receives `{ iso, code, number, isValid }` whenever the country or digits change." },
    { q: "How does validation work?", a: "Only digits are accepted, capped at each country's maximum length, and the number counts as valid once it reaches `minDigits` (default 7). It is a length check, not full libphonenumber validation." },
    { q: "Which countries are included?", a: "The exported `COUNTRIES` list has 29 countries; add entries there to support more. Set the starting country with `defaultCountry` as an ISO code such as \"GB\"." },
    { q: "Can I use it with the keyboard?", a: "Yes. Enter, Space or ArrowDown on the country button opens the list with its search box focused, Escape closes it, and each country is a button you can Tab to." },
  ],
  "pulse-dashboard-kpis": [
    { q: "How do I install the KPI cards?", a: "Run `npx shadcn@latest add @nexus-labs/pulse-dashboard-kpis`. It installs framer-motion and lucide-react." },
    { q: "How do I pass my own metrics?", a: "Pass `kpis` as an array of `{ label, value, delta?, lowerIsBetter?, trend? }`. To get the period switcher, pass `periods` instead, a record such as `{ \"7d\": [...], \"30d\": [...] }`, and pick the first one with `defaultPeriod`." },
    { q: "Does it need a chart library?", a: "No. Each sparkline is an inline SVG path built from the `trend` numbers and drawn in with Framer Motion. It is green when the change is good and red when it is bad, so latency or churn can use `lowerIsBetter`." },
    { q: "Does it support dark mode and reduced motion?", a: "Yes. It is styled with Tailwind `dark:` variants, and with prefers-reduced-motion on, the sparkline draw-in, hover lift and switcher slide are skipped." },
  ],
  "scroll-progress-bar": [
    { q: "How do I track one section instead of the whole page?", a: "Pass that section's ref as `targetRef`. Add `containerRef` if the section scrolls inside its own container, or pass your own `progress` motion value." },
    { q: "Can I use it as a horizontal bar at the top of the page?", a: "It is built as a vertical rail that fills from top to bottom. For a horizontal top bar, change the fill from `scaleY` to `scaleX` and swap the `height` and `width` values." },
    { q: "How do the markers work?", a: "`markerCount` (default 4) places evenly spaced dots on the rail, and each one switches to the fill color as progress passes it. Hide them with `showMarkers={false}`." },
    { q: "Is it accessible?", a: "It renders with role=\"progressbar\" and an `ariaLabel` you can change. With reduced motion, it follows the scroll directly without the spring." },
  ],
  "scroll-reveal-text": [
    { q: "How do I install scroll reveal text?", a: "Run `npx shadcn@latest add @nexus-labs/scroll-reveal-text`. It adds the ScrollRevealText component and installs framer-motion." },
    { q: "Can it reveal by word, character or line?", a: "Yes. Set `mode` to \"word\" (default), \"character\" or \"line\"; in line mode, separate lines with `\n` in `text`." },
    { q: "How do I control when the reveal starts and ends?", a: "`startOffset` and `endOffset` (0–1, defaults 0.05 and 0.75) set where in the element's scroll progress the reveal runs. `stagger` goes from 0 (all units at once) to 1 (fully one after another), and `blurAmount` sets the starting blur in pixels." },
    { q: "Does it respect reduced motion?", a: "Yes. With prefers-reduced-motion on, the text renders in `activeColor` with no scroll-linked animation." },
  ],
  "scrolling-testimonials": [
    { q: "How do I install scrolling testimonials?", a: "Run `npx shadcn@latest add @nexus-labs/scrolling-testimonials`. It has no extra dependencies: the scrolling is done with CSS keyframes, not Framer Motion." },
    { q: "How do I add my own testimonials?", a: "Pass a `testimonials` array of `{ id, quote, name, role, company?, avatar?, rating? }`. Cards without an `avatar` show colored initials, and `rating` renders stars when `showStars` is on." },
    { q: "How do I change the speed or direction of each column?", a: "`speed` sets the loop duration in milliseconds (default 35000), `columnSpeeds` overrides it per column, and `reverseColumns` flips individual columns to scroll upward. `pauseOnHover` (on by default) pauses a column under the cursor." },
    { q: "How does it behave on mobile and with reduced motion?", a: "The wall shows 1 column on mobile, 2 on tablets and up to 3 on desktop. With prefers-reduced-motion on, the columns stop scrolling." },
  ],
  "shader-flow": [
    { q: "How do I install Shader Flow?", a: "Run `npx shadcn@latest add @nexus-labs/shader-flow`. It installs framer-motion." },
    { q: "Is it a real WebGL shader?", a: "No. It is shader-style: large blurred gradient blobs animated with Framer Motion plus a light noise overlay. There is no canvas or WebGL, so it runs anywhere CSS blur works." },
    { q: "Which props does it take?", a: "`children` replaces the sample content, and `showContent={false}` hides it. `cursorReactive` (on by default) makes the blobs shift with the mouse, and `intensity` (\"low\", \"medium\", \"high\") scales that movement." },
    { q: "What happens with reduced motion?", a: "With prefers-reduced-motion on, the moving blobs are replaced by a static gradient." },
  ],
  "shooting-stars-grid": [
    { q: "How do I put my own content on top?", a: "Pass your heading and buttons as `children`; they replace the default content. Use `contentClassName` to adjust the content wrapper." },
    { q: "Which props control the stars?", a: "`starCount` (default 48, max 90) sets the twinkling stars, `shootingStarCount` (default 6, max 10) the streaks, `gridSize` the cell size in px and `speed` takes \"slow\", \"normal\", \"fast\" or a number. `interactive` makes the glow follow the pointer." },
    { q: "Does it respect reduced motion?", a: "Yes. With `reducedMotionFallback` left on (the default), the stars, streaks and glow stop animating for users who prefer reduced motion." },
    { q: "Does it work in light and dark mode?", a: "It uses a pale blue gradient in light mode and switches to a dark navy background with Tailwind's `dark:` variant. The default content uses `next/link`, so it is set up for Next.js." },
  ],
  "signup-form": [
    { q: "How do I install the signup form?", a: "Run `npx shadcn@latest add @nexus-labs/signup-form`. It pulls in the shadcn/ui input, label and button components plus framer-motion and lucide-react." },
    { q: "What does the form validate?", a: "First and last name need at least 2 characters, the email must look like an address, the password must meet `minPasswordLength` (default 8, never below 6), and the confirm field must match. The first failing rule is shown as an error message under the form." },
    { q: "How do I connect it to my auth backend?", a: "Pass an `onSubmit` handler; it receives the values after validation passes. While its promise is pending the button shows `loadingLabel`, on success it shows `successLabel`, and if it throws the form shows an error. The GitHub, Apple and Google buttons call `onSocialLogin(provider)`, and `showSocialLogins={false}` hides them." },
    { q: "Does it support dark mode and reduced motion?", a: "Yes. It uses Tailwind `dark:` variants, and with prefers-reduced-motion on, the entrance and button-label transitions are reduced to simple fades." },
  ],
  "sparkles": [
    { q: "How do I install the sparkles effect?", a: "Run `npx shadcn@latest add @nexus-labs/sparkles`. It adds the Sparkles component and installs framer-motion." },
    { q: "How do I use it as a background?", a: "Set `background` and it fills its nearest positioned parent as an absolute layer; otherwise size it with `className`. The page also shows line and starfield variations built from the same component." },
    { q: "Which props change how the particles look?", a: "`count` (36) is scaled by `density` (\"low\", \"medium\", \"high\"). `minSize`/`maxSize`, `speed`, `opacity`, `color`, `direction` (\"up\", \"down\", \"random\") and `enableGlow` shape the rest." },
    { q: "Can it react to the mouse?", a: "Yes. Set `interactive` to add a pointer glow, sparkles on hover and a burst of particles on click. With prefers-reduced-motion on, the particles stay still and dimmed." },
  ],
  "split-contact-glass": [
    { q: "How do I install Split Contact Glass?", a: "Run `npx shadcn@latest add @nexus-labs/split-contact-glass`. It installs framer-motion and lucide-react." },
    { q: "How do I send the form to my backend?", a: "Pass `onSubmit`, which receives `{ name, email, topic, message }`. If it returns a promise, the button shows a sending state and then a confirmation. Without `onSubmit` it only simulates a one-second send, so wire it up before going live." },
    { q: "How does the live local time work?", a: "`timeZone` takes an IANA zone such as \"Europe/Lisbon\" (the default). The time is formatted with `Intl.DateTimeFormat` and refreshes every 30 seconds." },
    { q: "What else can I customize?", a: "`heading`, `intro`, `email`, `location`, `replyTime` and `topics` fill the content, and `maxLength` (default 500) caps the message, with a counter that turns amber near the limit. It supports dark mode." },
  ],
  "squiggly-text": [
    { q: "How do I install squiggly text?", a: "Run `npx shadcn@latest add @nexus-labs/squiggly-text`. It adds SquigglyText and SquigglyWord and installs framer-motion, which is used only to detect reduced motion." },
    { q: "How is the wobble made?", a: "The component builds several SVG filters (`feTurbulence` + `feDisplacementMap`) with different seeds and switches between them every `stepDuration` ms. That gives a jittery hand-drawn look with no canvas." },
    { q: "Which props control the effect?", a: "`steps` (5) is the number of frames, `stepDuration` (80 ms) the time per frame, `scale` ([6, 8]) the distortion strength, and `baseFrequency` (0.02) and `numOctaves` (3) the noise. Use `SquigglyWord` to wobble only some words inside a heading." },
    { q: "Does it respect reduced motion?", a: "Yes. With prefers-reduced-motion on, it stops cycling and holds a single still frame." },
  ],
  "starfield-hero": [
    { q: "Which props change the particles?", a: "`particleCount` (default 300), `interactionRadius` (default 140px), `particleColor`, `activeColor` and `speed` (0.1 is slow and dreamy, 1 is snappy)." },
    { q: "How do I change the text and buttons?", a: "Use `title` (put \n in it for a line break), `subtitle`, and `primaryCTA` / `secondaryCTA` as `{ label, href, onClick }`. Pass `children` to replace the content completely." },
    { q: "Will the canvas animation slow down my page?", a: "The animation loop pauses when the hero is scrolled out of view or the tab is hidden. With reduced motion, the twinkle and cursor push are turned off." },
    { q: "How do I install it?", a: "Run `npx shadcn@latest add @nexus-labs/starfield-hero`, then import `InteractiveStarfieldHero`. It works on touch screens as well as with a mouse." },
  ],
  "step-flow": [
    { q: "How do I add my own steps?", a: "Pass `steps` as an array of `{ title, description, image, imageAlt, serial }`. `serial` defaults to 01, 02 and so on, and `defaultStep` picks the step shown first." },
    { q: "Can the steps advance automatically?", a: "Yes. Set `autoPlay` and `autoPlayInterval` in milliseconds (default 3500, minimum 1200)." },
    { q: "How do I change the highlight color?", a: "Use `highlightColor` (default a light gray). `textClassName` and `imageClassName` style the two columns." },
    { q: "Does it respect reduced motion?", a: "Yes. For users who prefer reduced motion the highlight moves without the spring and images swap with a plain fade instead of a blur." },
  ],
  "text-generate-effect": [
    { q: "How do I install the text generate effect?", a: "Run `npx shadcn@latest add @nexus-labs/text-generate-effect`. It adds the TextGenerateEffect component and installs framer-motion." },
    { q: "Can it start when the text scrolls into view?", a: "Yes. Set `trigger=\"viewport\"` to animate when the element enters the viewport, and `once` (default true) controls whether it replays. Changing `replayKey` restarts the animation." },
    { q: "Which props control the timing?", a: "`duration` (0.48s) is the time per segment, `stagger` (0.06s) the gap between segments, and `delay` the wait before the first. `blur` and `lift` toggle the blur-to-clear and upward motion, and `mode` picks word, character or line." },
    { q: "Is it accessible?", a: "Yes. The full sentence sits in a visually hidden span for screen readers while the animated pieces are hidden from them, and with prefers-reduced-motion on, the text appears without animation." },
  ],
  "text-reveal-card": [
    { q: "How do I set the visible and hidden text?", a: "`title` and `description` are the visible text, and `revealContent` is what appears on hover. You can also pass an `icon`, an `image` or `children`." },
    { q: "Does the reveal work on phones?", a: "Yes. On touch devices a tap toggles the hidden text, and on desktop keyboard focus reveals it in full." },
    { q: "What happens with reduced motion?", a: "The particle edge and cursor wipe are turned off and the hidden text simply fades in." },
    { q: "How do I install it?", a: "Run `npx shadcn@latest add @nexus-labs/text-reveal-card`. Use `intensity` (0.5 to 2.2) to size the glow and `disabled` to turn the effect off." },
  ],
  "typewriter-effect": [
    { q: "How do I install the typewriter effect?", a: "Run `npx shadcn@latest add @nexus-labs/typewriter-effect`. It adds the TypewriterEffect component and installs framer-motion for the cursor blink." },
    { q: "How do I rotate through several phrases?", a: "Pass an array to `text`. Each phrase is typed, held for `pauseDuration` ms, deleted at `deletingSpeed`, and the next one starts; set `loop` to repeat forever. Setting `deletingSpeed` to 0 switches phrases without the delete animation." },
    { q: "Is the text readable by screen readers and search engines?", a: "Yes. The full text is rendered in a visually hidden span while the animated letters are hidden from assistive tech, and `as` lets you render it as an `h1`, `h2`, `p`, `span` or `div`." },
    { q: "What happens with reduced motion?", a: "With prefers-reduced-motion on, it skips typing and shows the final phrase immediately. `onComplete` still fires." },
  ],
  "vector-tilt-scene": [
    { q: "How do I install the tilt card?", a: "Run `npx shadcn@latest add @nexus-labs/vector-tilt-scene`. It adds a single VectorTiltScene file and installs framer-motion." },
    { q: "How does the tilt work?", a: "It measures the pointer's offset from the card's center and maps it to `rotateX`/`rotateY` of up to 12 degrees, smoothed by springs (stiffness 240, damping 22) with a 1100px perspective. Leaving the card springs it back to flat." },
    { q: "How do I change the card's content?", a: "The component takes no props. The file is copied into your project, so edit the heading, text and Tailwind classes inside VectorTiltScene directly, or move the motion logic onto your own card." },
    { q: "Does it tilt on touch devices?", a: "The tilt is driven by mouse movement, so on phones and tablets the card mostly stays flat. It is meant as a desktop hover effect." },
  ],
  "warp-speed-card": [
    { q: "How do I use the warp speed effect?", a: "Wrap a few words in `WarpTextTrigger` inside your heading. `WarpSpeedCard` is an optional card wrapper for the section." },
    { q: "Can I change the beam color?", a: "Yes. Pass `beamColor` as an RGB triplet string, for example \"255,255,255\" for white." },
    { q: "Does it work on touch screens?", a: "The effect is triggered by mouse hover only, so on touch screens and with keyboard focus the text stays in its normal style and remains readable." },
    { q: "How do I install it?", a: "Run `npx shadcn@latest add @nexus-labs/warp-speed-card`. It comes with Pro and only depends on framer-motion." },
  ],
  "workbench-sidebar": [
    { q: "How do I install the Workbench Sidebar?", a: "Run `npx shadcn@latest add @nexus-labs/workbench-sidebar`. It installs framer-motion and lucide-react." },
    { q: "How do I pass my own navigation and projects?", a: "`items` takes `{ id, label, icon, count? }` with a Lucide icon, `projects` takes `{ id, label, color }`, and `workspace` and `user` fill the switcher and profile row. `usage` is a 0–1 value for the meter, or `null` to hide it." },
    { q: "How do I connect it to my router?", a: "Pass `activeId` and `onNavigate` to control the active item from your router, or use `defaultActiveId` to let the sidebar manage it." },
    { q: "Can it collapse to icons?", a: "Yes. The toggle at the bottom shrinks it from 252px to a 68px icon rail, and `defaultCollapsed` starts it collapsed. It supports dark mode through Tailwind `dark:` classes and skips the spring animations under reduced motion." },
  ],
  "spend-donut": [
    { q: "How do I install Spend Donut?", a: "Run `npx shadcn@latest add @nexus-labs/spend-donut`. It adds the component and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Can I pass my own categories and amounts?", a: "Not through props. The five categories and the Aug, Sep and Oct figures are the `CATS` and `MONTHS` constants at the top of the file, and the \"of $4,000 budget\" label is fixed text, so edit those to show your own numbers." },
    { q: "Which props change the ring?", a: "`thickness` sets the ring width in px (default 18) and the slice you point at grows by 6. `gap` sets the space between slices in px (default 4). `autoplay` is off by default and stops as soon as someone interacts." },
    { q: "Can I use it with the keyboard?", a: "Yes. Each category row is a button: focusing it highlights its slice, and Arrow keys, Home and End move between rows. A live region announces the amount, and the component follows the visitor's reduced-motion setting through Framer Motion's `MotionConfig`." },
  ],
  "traffic-bars": [
    { q: "How do I install Traffic Bars?", a: "Run `npx shadcn@latest add @nexus-labs/traffic-bars`. It adds the component and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Can I feed it my own traffic data?", a: "Not through props. The 28 days of Direct, Search and Referral numbers come from the `makeData` function in the file, and Week mode groups them into four weeks. Edit that function to use your own figures." },
    { q: "Which props change the colors and motion?", a: "`colors` takes three fills for Direct, Search and Referral (default `#0071e3`, `#64d2ff`, `#bf5af2`). `radius` rounds each slice (default 2), `stagger` is the delay between days when slices regroup (default 12 ms), and `theme` is \"auto\", \"light\" or \"dark\"." },
    { q: "Can I explore the chart with the keyboard?", a: "Yes. Focus the chart and use the arrow keys to move between columns, Home and End to jump to the first or last, and Escape to clear. A live region reads out each column, and a hidden table lists the values." },
    { q: "Does it use a chart library?", a: "No. The bars are SVG rects animated with Framer Motion springs, and framer-motion is the only dependency. Switching Day to Week moves each day's slices into their week's column." },
  ],
  "goo-reorder": [
    { q: "How do I install Goo Reorder?", a: "Run `npx shadcn@latest add @nexus-labs/goo-reorder`. It adds the component and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the rows and read the new order?", a: "Pass `items` as an array of `{ id, label, color }`; `color` tints the numbered badge. `onReorder` receives the new array after a drag or an arrow-key move. `items` only sets the starting order, so later changes to the prop do not update the list." },
    { q: "Can rows be moved without a mouse?", a: "Yes. Each row is focusable, and `ArrowUp` or `ArrowDown` moves the focused row one place and calls `onReorder`. The row's label announces its position, such as \"position 2 of 5\"." },
    { q: "How is the liquid effect made?", a: "One SVG filter (a blur plus a color matrix) is applied to the whole list, which merges neighbouring rows into a liquid shape while the text stays sharp. Dragging is Framer Motion's `Reorder` component, limited to the vertical axis." },
  ],
  "dot-sphere": [
    { q: "How do I install Dot Sphere?", a: "Run `npx shadcn@latest add @nexus-labs/dot-sphere`. It adds the component and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Which props change the sphere?", a: "`dots` (default 420), `radius` in px (130) and `dotSize` (3.4) set its size and density. `speed` (30) is the idle spin and `repel` (55) is how hard the pointer pushes dots, both 0 to 100. `color` and `accent` override the dot and ripple colors." },
    { q: "How does it respond to the pointer and keyboard?", a: "The pointer pushes dots away, dragging spins the sphere, and a tap sends a ripple. When focused, the arrow keys spin it and Enter or Space sends a ripple. Set `interactive` to false to turn all of this off, including the hint." },
    { q: "Does it respect prefers-reduced-motion?", a: "Yes. It is drawn on a 2D canvas, and framer-motion is used only to read the setting. With reduced motion on, it renders without the idle spin and ripples are disabled; dragging or the arrow keys still turn it step by step." },
    { q: "Does it keep animating when it is off screen?", a: "No. The animation loop stops when the canvas scrolls out of view or the browser tab is hidden, and it resumes when it is visible again." },
  ],
  "price-odometer": [
    { q: "How do I install Price Odometer?", a: "Run `npx shadcn@latest add @nexus-labs/price-odometer`. It adds `PriceOdometer` and `RollingNumber` and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the prices and the seat limit?", a: "`monthlyRate` (default 15) and `yearlyRate` (default 12) are per-seat prices, and `maxSeats` (default 100) is the top of the slider, which starts at 8 seats. The Save badge is calculated from the two rates. The `$` and `/mo` text is fixed." },
    { q: "Can I use the rolling number on its own?", a: "Yes. `RollingNumber` is exported next to `PriceOdometer`. Pass a `value` and each digit rolls on its own spring, with columns sliding in or out as the number gains or loses digits. Thousands use en-US commas." },
    { q: "Can I change the accent color?", a: "Yes. `accent` (default `#0071e3`) colors the slider fill, the Save badge and the focus outline on the Monthly and Yearly buttons." },
    { q: "Are the slider and billing toggle keyboard friendly?", a: "Yes. Seats use a native range input, so arrow keys work, and Monthly and Yearly are buttons with `aria-pressed`. The total sits in a `role=\"status\"` region." },
  ],
  "cloth-banner": [
    { q: "How do I install Cloth Banner?", a: "Run `npx shadcn@latest add @nexus-labs/cloth-banner`. It adds the component and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I change the text and colors?", a: "`title` (default \"Launch Week\") and `subtitle` are painted onto the cloth as one line each. `from` (default `#0071e3`) and `to` (default `#5e5ce6`) set the gradient from top left to bottom right." },
    { q: "How do I know when the banner was dismissed?", a: "Pass `onDismiss`. It is called once the banner has dropped away, whether it was yanked down or the Dismiss button was pressed. The component does not remember the choice, so store it yourself, for example in localStorage." },
    { q: "Is it a physics library?", a: "No. The cloth is a small simulation inside the component, drawn on a 2D canvas with five pins holding it to the rail. Framer Motion only animates the \"dismissed\" message and button, so framer-motion is the one dependency." },
    { q: "How does it work without a mouse or with reduced motion?", a: "Dragging needs a pointer, but Dismiss, Breeze and Hang it back up are real buttons. With prefers-reduced-motion, the ambient sway is off and `autoplay` does nothing; gravity, grabbing and the Breeze button still work." },
  ],
  "usage-stack": [
    { q: "How do I install Usage Stack?", a: "Run `npx shadcn@latest add @nexus-labs/usage-stack`. It adds the component and installs framer-motion and matter-js. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Can I change the pricing tiers?", a: "Not through props. Tiers come from the exported `USAGE_TIERS` array (Free up to 50,000 requests, Growth at $0.25 per 1,000 up to 250,000, then Scale at $0.15 per 1,000). Edit it; `usagePrice(n)` is exported too. The \"First 50k are free\" label is fixed text." },
    { q: "How do I set the starting volume and read changes?", a: "`defaultValue` is the starting requests per month (default 120000), rounded to the nearest 10,000 and kept between 0 and 600,000. `onChange(requests, price)` fires whenever the volume changes, with the monthly price in dollars." },
    { q: "Which keys control the slider?", a: "The slider is focusable. Arrow keys change the volume by 10,000 requests, PageUp and PageDown by 50,000, and Home and End jump to 0 and 600,000. Its `aria-valuetext` reads the requests, tier and monthly price." },
    { q: "How are the blocks simulated?", a: "matter-js runs the physics, and each block is a DOM element moved with a CSS transform. The simulation pauses when the bin is off screen or the tab is hidden. `autoplay` is off by default and does not run when reduced motion is preferred." },
  ],
  "ink-theme-switch": [
    { q: "How do I install Ink Theme Switch?", a: "Run `npx shadcn@latest add @nexus-labs/ink-theme-switch`. It adds the component and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Does it change my site's theme?", a: "No. It themes only its own panel and never touches the page or the document's classes. Use `onChange`, which receives a boolean `dark`, to apply the choice to your own theme. `defaultDark` (default false) starts the panel dark." },
    { q: "Can I put my own UI inside the panel?", a: "Not through props. There is no `children`; the panel is a fixed 320 by 300 px sample settings screen drawn by the internal `Panel` component, so replace that to show your own light and dark layouts. `className` adds classes to the panel." },
    { q: "How is the ink effect made?", a: "A dark copy of the panel sits on top, revealed by a CSS `clip-path` circle centered on the switch. Framer Motion animates its radius, about 0.9s out and 0.7s back. The sun-to-moon change is an SVG mask plus rays that scale away." },
    { q: "Is the switch accessible?", a: "The toggle is a native button with `role=\"switch\"`, `aria-checked` and the label \"Dark mode\", so it works with Enter and Space. Only the visible copy of the panel is exposed to screen readers; the other is `aria-hidden`." },
  ],
  "bend-text": [
    { q: "How do I install Bend Text?", a: "Run `npx shadcn@latest add @nexus-labs/bend-text`. It adds the component and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I change the text on the string?", a: "Pass `text` as one repeat of the line; it is repeated four times along an SVG `textPath` and drifts slowly along the string. The default ends with a separator and a space so repeats do not run together. With reduced motion on, the drift stops." },
    { q: "Can I change the color and the caption?", a: "`accent` (default `#0071e3`) colors the grab point and the focus ring. `hint` is the caption under the stage; pass an empty string to hide it. The text color follows light and dark mode through the `dark:` classes." },
    { q: "How do I react when the string is plucked?", a: "Pass `onPluck`. It is called on release with how far the string was pulled from rest, in stage units, so you can trigger something on a big pull. Keyboard plucks call it too." },
    { q: "Can I pluck it with the keyboard?", a: "Yes. The stage is focusable with `role=\"button\"`. Enter, Space and ArrowUp pluck it upward, ArrowDown pulls it down, and ArrowLeft and ArrowRight pluck from other points on the string. The spring is underdamped, so it overshoots a few times before settling." },
  ],
  "pull-cord": [
    { q: "How do I install Pull Cord?", a: "Run `npx shadcn@latest add @nexus-labs/pull-cord`. It installs framer-motion. Pull Cord is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I run code when the light switches?", a: "Pass `onChange`. It receives the new boolean when the cord is pulled or Enter/Space is pressed, but not for the `autoplay` demo. `defaultOn` sets the starting state and defaults to `false`." },
    { q: "How do I change the text on the panel?", a: "Use `onText` (default \"Lights on.\"), `offText` (default \"Lights off.\") and `hint` (default \"Pull the cord.\"). The panel is 320px wide and scales down to fit a narrower parent." },
    { q: "Can I use it from the keyboard?", a: "Yes. The bead is a button with `role=\"switch\"`, and Enter or Space tugs the cord and toggles the light. With a pointer you grab the bead, pull it past its slack and let go." },
    { q: "How is the cord animated?", a: "The cord is a 12-segment verlet rope stepped in a `requestAnimationFrame` loop and drawn as an SVG path. Framer Motion fades the panel colour and glow. The light only fills the panel, never the page." },
  ],
  "polaroid-develop": [
    { q: "How do I install Polaroid Develop?", a: "Run `npx shadcn@latest add @nexus-labs/polaroid-develop`. It installs framer-motion. Polaroid Develop is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I develop my own photo?", a: "Pass `src` and `alt`. Add `caption` to have it written by hand once developed; without it no caption appears. `onDeveloped` is called with the caption, or `alt` if there is none. Without `src`, drawn scenes are shown." },
    { q: "How do I change the built-in scenes?", a: "Pass `scenes` as objects of `{ sky, sea, sun, land, caption }`, where `sky` is a pair of gradient colours. The New photo button steps to the next scene and restarts the developing." },
    { q: "How does shaking develop the photo, and can I use the keyboard?", a: "The faster you drag, the faster the haze clears, and it also develops slowly on its own. Focus the photo and press Enter or Space to shake it. Under reduced motion, that key advances the development in steps instead." },
  ],
  "weather-puck": [
    { q: "How do I install Weather Puck?", a: "Run `npx shadcn@latest add @nexus-labs/weather-puck`. It installs framer-motion. Weather Puck is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Which props does it take, and can I read the chosen time?", a: "The only prop is `autoplay` (default `false`), which sweeps the light across the day until someone drags it. There is no value or change callback; the hour name and clock are rendered inside the component." },
    { q: "What times and hour names does it show?", a: "The hour name is one of Before dawn, Sunrise, Midday, Golden hour, Dusk or Night. The clock runs from 04:30 to 23:30 as the puck moves left to right. Moving it up or down only changes the dot glow." },
    { q: "Can I move the puck with the keyboard?", a: "Yes. The puck is a focusable `role=\"slider\"` named \"Time of day\", and the Left and Right arrow keys move it 30px at a time. Its `aria-valuetext` reads the hour name and clock, such as \"Dusk\" with the time." },
    { q: "How is it drawn?", a: "The dot field is a 2D canvas redrawn every frame. The sky, sun, ridges and labels are interpolated from the puck position with Framer Motion. The resting dots follow the site's `dark` class. It is 440px wide at most and shrinks to fit." },
  ],
  "step-player": [
    { q: "How do I install Step Player?", a: "Run `npx shadcn@latest add @nexus-labs/step-player`. It installs framer-motion. Step Player is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the steps and the color?", a: "Pass `steps` as objects of `{ t, b }`, a title and a one-line body, in the order they play. `accent` (default `#0071e3`) colors the filling bar, finished dots and the \"Step n of m\" line. An empty array renders nothing." },
    { q: "How long does each step last, and does it loop?", a: "`stepDuration` is in seconds and defaults to 3.2. After the last step it wraps back to the first. `autoplay` defaults to `true`; pass `autoplay={false}` to start paused, and the play button still works." },
    { q: "Can people jump to a step?", a: "Yes. Each dot is a button with `role=\"tab\"` labelled with the step title. Selecting one jumps there and restarts its progress bar. The round button plays and pauses. There is no callback for the current step." },
    { q: "Can I pass a className or change the width?", a: "No. The props are `accent`, `steps`, `stepDuration` and `autoplay`, and the card is a fixed 320px wide. To resize it, edit the width class in the copied source file." },
  ],
  "standing-calendar": [
    { q: "How do I install Standing Calendar?", a: "Run `npx shadcn@latest add @nexus-labs/standing-calendar`. It installs framer-motion. Standing Calendar is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I pass my own data?", a: "Pass `data` as `number[][]`: one array of 7 counts per week, Monday to Sunday. Without it the component generates sample data for `weeks` weeks (default 30). A standing column is `3 + count * 6` px tall." },
    { q: "How do counts map to colors?", a: "`levels` takes five colors. A count of 0 uses the first, 1 to 2 the second, 3 to 5 the third, 6 to 8 the fourth and 9 or more the fifth. The default first color follows light and dark mode." },
    { q: "How do I switch between flat and standing?", a: "It starts flat, with Flat and Standing toggle buttons below the grid. There is no prop to start standing. `autoplay` (default `false`) stands up and lies down on a loop until someone interacts." },
    { q: "How does hover work?", a: "Hovering a day turns its top orange and shows \"Week n, Day: value\" above the grid, next to the total count. Hover uses pointer events only, so there is no keyboard equivalent for reading a day." },
  ],
  "heat-field": [
    { q: "How do I install Heat Field?", a: "Run `npx shadcn@latest add @nexus-labs/heat-field`. The registry lists framer-motion as its dependency. Heat Field is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I change the size of the heat and the hint text?", a: "`radius` sets the spread of heat around the pointer in px and defaults to 46; held heat spreads a little wider. `hint` sets the line under the field, and an empty string hides it." },
    { q: "How do I leave heat behind?", a: "Press and hold while moving over the dots. Held heat stays and cools slowly after release. Without pressing, dots heat up quickly under the pointer and cool once it moves on." },
    { q: "Does it work with touch or the keyboard?", a: "It listens to pointer events, so mouse, touch and pen all work. The field uses `touch-none`, which stops touch scrolling over it. There is no keyboard interaction; it is exposed as a single labelled image." },
    { q: "What is it built with?", a: "Two 2D canvases, one for the grey dots and one for the heat layer, plus an SVG blur and color-matrix filter that makes the dots melt together. There is no WebGL. The heat ramps from yellow through orange and red to violet." },
  ],
  "animated-tabs": [
    { q: "How do I install Animated Tabs?", a: "Run `npx shadcn@latest add @nexus-labs/animated-tabs`. It is free and installs framer-motion. The install adds `AnimatedTabs`, `Switch`, `ElasticTabs` and `DocumentTabs`." },
    { q: "What is the difference between AnimatedTabs, ElasticTabs and DocumentTabs?", a: "`AnimatedTabs` is a fixed settings panel with switches (props `accent` and `autoplay`). `ElasticTabs` is a stretchy-pill tab bar for your own content. `DocumentTabs` is a browser-style strip. `Switch` is exported on its own too." },
    { q: "How do I give ElasticTabs my own tabs?", a: "Pass `tabs` as `{ id, label, content }` items, where `content` is any React node. `label` names the tab list (default \"Dashboard\") and `onChange` receives the tab id. Left, Right, Home and End move between tabs." },
    { q: "How do I reorder and close DocumentTabs?", a: "Drag a tab to reorder it. On a focused tab, Alt with an arrow moves it, Delete or Backspace closes it, and plain arrows switch tabs. It holds at most 6 tabs, and closing the last one restores `initialTabs`." },
    { q: "How does it handle reduced motion?", a: "`ElasticTabs` and `DocumentTabs` check it: their `autoplay` never runs, and the pill and panel stop springing or sliding. `AnimatedTabs` and `Switch` do not check it." },
  ],
  "slosh-slider": [
    { q: "How do I install Slosh Slider?", a: "Run `npx shadcn@latest add @nexus-labs/slosh-slider`. It installs framer-motion. Slosh Slider is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I read and set the value?", a: "`defaultValue` sets the start, 0 to 100, default 55. `onChange` is called with the rounded value whenever it changes, following the handle rather than the lagging liquid. There is no controlled `value` prop." },
    { q: "How do I change the label and color?", a: "`label` sets the text above the track and the slider's accessible name, default \"Volume\". `accent` colors the liquid and the focus ring, default `#0071e3`. The track is a fixed 300px wide." },
    { q: "Does it work with the keyboard?", a: "Yes. The track is a `role=\"slider\"` with `aria-valuenow`. Arrow keys move the value by 5%, and Home and End jump to 0 and 100." },
    { q: "How does the sloshing work?", a: "The handle follows the pointer exactly. The liquid is an SVG path that chases it on a loose spring and leans with its speed, up to 26px, then settles. It uses Framer Motion springs and velocity, not a physics library." },
  ],
  "tear-off-ticket": [
    { q: "How do I install Tear-off Ticket?", a: "Run `npx shadcn@latest add @nexus-labs/tear-off-ticket`. It installs framer-motion. Tear-off Ticket is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I change the ticket text?", a: "Use `title`, `venue`, `date` and `seat`; `seat` appears on the stub. The \"Exhibition\" and \"Admit one\" labels are fixed text in the source file, so edit the copied component to change them." },
    { q: "How far do I pull to tear it?", a: "Drag the stub right, with downward movement counting at 0.6, until you reach about 150px of pull. Let go earlier and it springs back. Past that it tears, swings on its last tooth and drops. A New ticket button then resets it." },
    { q: "Can I tear it without dragging?", a: "Yes. The stub is a focusable `role=\"button\"`, and Enter or Space tears it. The `autoplay` prop (default `false`) tugs, tears and resets on a loop until someone grabs the stub." },
    { q: "Can I run code when the stub tears off?", a: "There is no callback prop; the props are `title`, `venue`, `date`, `seat` and `autoplay`. To react to a tear, add your handler to the `tear` function in the copied source file." },
  ],
  "seek-search": [
    { q: "How do I install Seek Search?", a: "Run `npx shadcn@latest add @nexus-labs/seek-search`. It installs framer-motion. Seek Search is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the suggestions and react to a click?", a: "Pass `suggestions` as an array of strings. They are filtered in the browser as the user types (case-insensitive match, with the matched text in bold) and nothing is fetched. `onSelect` receives the suggestion that was clicked." },
    { q: "How do I close it from the keyboard?", a: "Press Escape to fold it back and clear the query. Clicking away also folds it, but only when the field is empty; with text in it, it stays open. The closed button has `aria-expanded` set." },
    { q: "Which props change the field itself?", a: "`placeholder` (default \"Search files\") is also the field's accessible name, and `maxLength` (default 64) caps how many characters the query can hold. The pill is 300px wide when open." },
  ],
  "capsule-toggles": [
    { q: "How do I install Capsule Toggles?", a: "Run `npx shadcn@latest add @nexus-labs/capsule-toggles`. It is free and installs framer-motion. The file exports both the single `CapsuleToggle` switch and the `CapsuleToggles` settings panel." },
    { q: "How do I use one switch on its own?", a: "Render `CapsuleToggle` with `checked`, `onChange` and `label`, all required. It is a button with `role=\"switch\"` and `aria-checked`, and `label` is its accessible name." },
    { q: "How do I set up the panel rows?", a: "Pass `rows` as `{ id, label, hint, color, on }`. `on` is only the starting state, `hint` shows under the label while the row is on, and `title` (default \"Controls\") is the heading. The panel keeps its own state." },
    { q: "How do I change the colours?", a: "`onColor` (default `#34c759`) sets the ball colour and glow when on, and `offColor` sets the ball when off. Without `offColor`, a grey that changes in dark mode is used. In the panel, each row's `color` is its `onColor`." },
    { q: "Does the animation run if I change `checked` from code?", a: "Yes. The ball stretches into a pill whenever `checked` changes, whether the user pressed the switch or your own state updated it." },
  ],
  "layout-switch": [
    { q: "How do I install Layout Switch?", a: "Run `npx shadcn@latest add @nexus-labs/layout-switch`. It installs framer-motion. Layout Switch is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Which layouts are there, and how do I switch them?", a: "There are four: \"grid\", \"row\", \"feature\" and \"pile\", chosen with the segmented buttons above the photos (each has `aria-pressed`). The photos spring from their old box to the new one instead of fading." },
    { q: "How do I use my own photos?", a: "There is no photos prop. The six photos are a `PHOTOS` array at the top of the file, each with an `id`, a `title` and a CSS background in `art`. Edit that array; the grid layout is sized as 3 columns by 2 rows." },
    { q: "How does opening a photo work?", a: "Click a photo and it grows to fill the frame while the others dim. Click it again or press Escape to put it back. Choosing a layout button also closes it. Each photo is a button labelled \"Open\" or \"Close\" plus its title." },
  ],
  "magnify-dock": [
    { q: "How do I install Magnify Dock?", a: "Run `npx shadcn@latest add @nexus-labs/magnify-dock`. It installs framer-motion. Magnify Dock is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set my own icons?", a: "Pass `apps` as an array of `DockApp`: `id`, `label`, `bg` (any CSS background) and `glyph` (any React node). Without it you get seven sample apps, from Home to Settings." },
    { q: "How do I change how much the icons grow?", a: "It is not a prop. Edit the constants at the top of the file: `BASE` (46) is the resting size in px, `MAX` (76) the largest size, and `RANGE` (150) how far from the pointer the swelling reaches." },
    { q: "What happens when I click an icon, and can I run my own code?", a: "The icon bounces and a dot appears under it, with Home marked as running from the start. There is no click callback prop, so to run your own action edit the `onLaunch` handler in the source." },
    { q: "Does it work with the keyboard?", a: "Icons are buttons inside a `role=\"toolbar\"` named \"Dock\", with a visible focus outline, and focusing one shows its label. The swelling follows the pointer only, so keyboard users see no magnification." },
  ],
  "runaway-button": [
    { q: "How do I install Runaway Button?", a: "Run `npx shadcn@latest add @nexus-labs/runaway-button`. It installs framer-motion. Runaway Button is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I know when someone cancels or keeps the plan?", a: "Pass `onCancel` for when the cancel button is finally clicked or activated from the keyboard, and `onKeep` for when \"Keep my plan\" is clicked. Both are optional and take no arguments." },
    { q: "How many times does the button dodge?", a: "Four times (`MAX_TRIES`). Each time the pointer comes close it jumps to a new spot, and its label changes through the exported `RUNAWAY_LINES`, from \"Yes, cancel\" to \"Okay, cancel\". Then it settles back and can be clicked." },
    { q: "Is it usable without a mouse?", a: "Yes. While the cancel button has keyboard focus it never moves, and Enter or Space activates it. After a keyboard choice, focus moves to the \"Start over\" button on the result screen." },
    { q: "Can I change the dialog text?", a: "There are no text props. The heading, the body line and \"Keep my plan\" are written in the JSX, and the cancel labels come from the `RUNAWAY_LINES` array. Edit those in the source." },
  ],
  "ruler-picker": [
    { q: "How do I install Ruler Picker?", a: "Run `npx shadcn@latest add @nexus-labs/ruler-picker`. It installs framer-motion. Ruler Picker is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the range and read the value?", a: "`min` (default 0), `max` (default 90) and `defaultValue` (default 25) set the range and start. `onChange` is called with the new number as it changes. It is uncontrolled, so there is no `value` prop." },
    { q: "What happens at 60 and above?", a: "The big number switches to an hours format such as 1:05 with an \"hr\" label; below 60 it shows the number with `unit` (default \"min\"). Preset buttons read \"N min\", or \"N hr\" from 60." },
    { q: "How do I change the presets and colour?", a: "`presets` is an array of numbers (default `[5, 15, 30, 60]`); tapping one springs the ruler there. `accent` (default `#ff9f0a`) colours the needle and the selected preset." },
    { q: "How do I move it with drag or keyboard?", a: "Drag or fling the ruler and it glides with momentum, then snaps to a whole unit. The ruler is focusable with `role=\"slider\"`, and the Left and Right arrow keys move it one unit." },
  ],
  "bending-rail": [
    { q: "How do I install Bending Rail?", a: "Run `npx shadcn@latest add @nexus-labs/bending-rail`. It installs framer-motion. Bending Rail is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the label, range and starting value?", a: "Use `label` (default \"Volume\"), `min` (0), `max` (100), `defaultValue` (40) and `unit` (\"%\"). `onChange` is called whenever the rounded value changes. It is uncontrolled, so there is no `value` prop." },
    { q: "How does the rail bend?", a: "Drag the knob up or down off the groove and the rail bends toward it, with the pull damped and capped. A dashed ghost knob stays on the groove at the real value. Release and the rail springs straight. It is drawn with SVG paths." },
    { q: "What keyboard keys does it support?", a: "The knob is a button with `role=\"slider\"` and ARIA min, max and now values. Arrow Right or Up adds 1 and Arrow Left or Down subtracts 1; holding Shift changes it by 10. `accent` also colours the focus ring." },
  ],
  "fold-note": [
    { q: "How do I install Fold Note?", a: "Run `npx shadcn@latest add @nexus-labs/fold-note`. It installs framer-motion. Fold Note is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I change the text on the note?", a: "Use `title` (default \"Store Credit\"), `amount` (a string, default \"50\", printed as given), `serial` for the fine print, and `backLabel` (default \"Thanks\") for the word on the back of the folding half." },
    { q: "How do I know when it has folded?", a: "Pass `onFoldChange`. It is called with `true` when the note snaps shut and `false` when it opens again, including when autoplay folds it. Both arguments are booleans." },
    { q: "How do I fold it, and does it work with a keyboard?", a: "Drag the right half over: past halfway, or with a fast leftward flick, it snaps shut with a bounce; otherwise it opens back. A tap toggles it. It is focusable, and Space toggles it." },
    { q: "How is the 3D fold made, and can I recolour the note?", a: "It uses CSS `perspective` and a `rotateY` turn on the centre crease, with a dark overlay for shading and `backfaceVisibility` to show the back. The colours and size are constants in the source, not props." },
  ],
  "streak-counter": [
    { q: "How do I install Streak Counter?", a: "Run `npx shadcn@latest add @nexus-labs/streak-counter`. It installs framer-motion. Streak Counter is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the streak length?", a: "Pass `start` (default 11). The count lives in component state and the \"Log today\" button adds one. There is no callback prop, so it resets when the component remounts; to save it, edit the source." },
    { q: "How does the flame change over time?", a: "The flame, today's dot and the button shift colour over the eight days logged after `start`, then stay at the hottest shade. Each log also bursts 16 embers that fly out and fall back into the flame." },
    { q: "Do the weekday letters match the real calendar?", a: "No. The strip shows the last seven streak days with today on the right, and the M to S letters come from the streak number, not from the current date. Treat them as decoration." },
  ],
  "flight-tracker": [
    { q: "How do I install Flight Tracker?", a: "Run `npx shadcn@latest add @nexus-labs/flight-tracker`. It installs framer-motion. Flight Tracker is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the route, times and flight number?", a: "Pass `from`, `to`, `flight`, `departs` and `arrives` as strings (defaults NYC, LON, \"MK 214\", \"8:30 PM\", \"8:40 AM\"). The countdown comes from `minutes` (default 410) and the remaining distance from `miles` (default 3459)." },
    { q: "Does it show real flight data?", a: "No, it fetches nothing. Progress is a value inside the component that starts at 35% of the route, and there is no progress prop. With `autoplay` (off by default) the plane flies the arc on a loop, about 22 seconds per flight." },
    { q: "What do the status line and the Details panel show?", a: "The status reads \"On time\", then \"Landing in N min\" past 85% of the route, then \"Landed\". Details expands altitude, speed and distance left. Distance uses `miles`; altitude and speed are worked out from the plane's position on the arc." },
    { q: "How is the plane drawn along the curve?", a: "An SVG path is measured with `getPointAtLength` on every frame, and the plane is rotated to follow the curve, animated with Framer Motion. With prefers-reduced-motion on, the pulsing status dot stops pulsing; the plane itself is not changed." },
  ],
  "swipe-stack": [
    { q: "How do I install Swipe Stack?", a: "Run `npx shadcn@latest add @nexus-labs/swipe-stack`. It adds both SwipeStack and the SwipeRows variant and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "What data does each card take?", a: "Pass `payments` as `{ amount, from, to, note, when, hue }`, top card first. `amount` and `when` are display strings you format yourself, and `hue` (0 to 360) colors the two avatars. \"Load more\" deals the same list again." },
    { q: "How do I find out what the user decided?", a: "Pass `onDecide`. It is called after a card is thrown with the payment and an `approved` boolean: true for a right swipe or the approve button, false for a left swipe or the flag button." },
    { q: "Can I use it without dragging?", a: "Yes. Two buttons labelled \"Approve payment\" and \"Flag payment\" throw the top card. In SwipeRows, a focused row archives on the right arrow key and deletes on Delete or Backspace." },
    { q: "How do I use SwipeRows for an inbox list?", a: "Pass `items` as `{ id, from, subject, time, color }` and an optional `title` (default \"Inbox\"). Handle `onArchive`, `onDelete`, `onFlag` and `onUndo`; an Undo bar appears after an archive or delete." },
  ],
  "context-meter": [
    { q: "How do I install Context Meter?", a: "Run `npx shadcn@latest add @nexus-labs/context-meter`. It installs framer-motion. Context Meter is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the categories and the window size?", a: "Pass `categories` as `{ id, label, color, tokens }` with `tokens` in thousands, and `limit` in thousands (default 200). The grid is always 40 by 5 dots, so each dot is `limit` divided by 200. Categories are read once on mount." },
    { q: "What grows, and what does Compact chat do?", a: "The category named by `growId` (default \"conv\") gains 2.2K every 380 ms until the window is nearly full. Compact chat drops its dots and sets it back to 6.2K. The growth runs inside the component, so no prop turns it off." },
    { q: "What happens when I hover or focus a category?", a: "Each legend row is a button. Hovering or focusing it dims every dot outside that category, so keyboard users get the same highlight. The grid is a `meter` role with the token total as its value text." },
    { q: "Can I use my own colors, including theme variables?", a: "Yes. `color` accepts any CSS color, including `var()`. The default System prompt category uses `--cm-ink`, which is near-black in light mode and near-white in dark mode. `autoplay` is off by default." },
  ],
  "assign-picker": [
    { q: "How do I install Assign Picker?", a: "Run `npx shadcn@latest add @nexus-labs/assign-picker`. It installs framer-motion. Assign Picker is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I pass in people?", a: "Pass `people` as `{ id, name, role, colors }`, where `colors` is two colors for the avatar gradient. Avatars are gradient circles with initials drawn on top, so no images are loaded. Without `people` it shows five sample people." },
    { q: "How do I read or preselect the selection?", a: "`onChange` receives the selected ids in the order they were picked, and `defaultValue` sets the ids selected on first render. There is no controlled `value` prop, so the component holds the selection itself." },
    { q: "What does the pill label say?", a: "It reads \"Assign\" when empty, the first name for one person, \"Ana and Ben\" style first names for two, and \"N people\" for three or more. Up to three avatars stack in the pill, with a +N chip beyond that." },
    { q: "Is the menu keyboard and screen reader friendly?", a: "The pill is a button with `aria-haspopup=\"listbox\"` and `aria-expanded`. The menu is a multiselectable listbox whose options carry `aria-selected`. Escape closes the menu and returns focus to the pill." },
  ],
  "component-layers": [
    { q: "How do I install Component Layers?", a: "Run `npx shadcn@latest add @nexus-labs/component-layers`. It installs framer-motion. Component Layers is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Can I explode my own component instead of the music player?", a: "There is no `children` or layers prop. The four layers (Surface, Spacing, Layout, Content) come from the exported `COMPONENT_LAYERS` array in the file, so edit its names, notes and `render` functions, and the Player function, to show your own card." },
    { q: "Which props can I set?", a: "Only two. `accent` (default \"#0071e3\") colors the cover art and the hovered layer's outline and leader line. `autoplay` (off by default) explodes and reassembles the card on a loop until someone uses the toggle." },
    { q: "How do I switch views, and what does hovering do?", a: "The Assemble and Explode buttons switch views and report their state with `aria-pressed`. Hovering a layer in the exploded view outlines it and colors its leader line with `accent`." },
    { q: "Does it use WebGL or three.js?", a: "No. It is CSS 3D transforms driven by Framer Motion: the card is tilted with `rotateX` and `rotateZ` under a 1400 px perspective, and each layer is pushed out along z with a spring." },
  ],
  "radio-cards": [
    { q: "How do I install Radio Cards?", a: "Run `npx shadcn@latest add @nexus-labs/radio-cards`. It is a free component and installs framer-motion." },
    { q: "How do I define the plans and the starting selection?", a: "Pass `options` as `{ id, title, description, meta?, features? }`. `meta` shows on the right, such as a price, and `features` appear as chips on the selected card. `defaultValue` is an option id; without it the second option starts selected." },
    { q: "How do I get the chosen plan?", a: "Pass `onChange`; it receives the option `id` when the user picks one. There is no controlled `value` prop. The Continue button only shows the plan name and has no click handler, so add your own action there." },
    { q: "Are these real radio inputs?", a: "Yes. Each card wraps a visually hidden `input type=\"radio\"` inside a `fieldset` with a screen-reader legend, so grouping and keyboard behavior come from the browser. The focused card gets a visible outline." },
    { q: "How do I change the color or let it demo itself?", a: "`accent` (default \"#0071e3\") colors the ring, the dot, the feature check marks and the button. `autoplay` is off by default; when on it cycles the options until someone interacts, and it does not call `onChange`." },
  ],
  "glass-lens": [
    { q: "How do I install Glass Lens?", a: "Run `npx shadcn@latest add @nexus-labs/glass-lens`. It adds both GlassLens and the ZoomLens variant and installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I put my own content under the GlassLens?", a: "Pass it as `children`; it fills a surface of `width` by `height` (defaults 520 by 300). `size` sets the lens diameter (default 150) and `zoom` the centre magnification (default 1.45). Children render four times, so keep them static." },
    { q: "How is the color fringe made without a shader?", a: "The lens holds three copies of your content: one at `zoom`, one slightly larger tinted red, one slightly smaller tinted blue, blended together. Their gap grows toward the rim, which looks like chromatic aberration. There is no canvas or WebGL." },
    { q: "How do I magnify my own image with ZoomLens?", a: "Pass `image` (a URL or data URI), `darkImage` for dark mode, and `aspectRatio` as width divided by height. Zoom starts at `defaultZoom` (2.6) within `minZoom` 1.5 and `maxZoom` 4; the wheel, slider and +/- keys change it." },
    { q: "Can I use it from the keyboard or with reduced motion?", a: "Both lenses are focusable and move with the arrow keys; ZoomLens also zooms with plus and minus. Under reduced motion, ZoomLens follows the pointer directly, fades instead of scaling in, and its `autoplay` never runs." },
  ],
  "rotating-headline": [
    { q: "How do I install Rotating Headline?", a: "Run `npx shadcn@latest add @nexus-labs/rotating-headline`. It is a free component and installs framer-motion." },
    { q: "How do I change the text and the rotating words?", a: "`lead` is the fixed text (default \"Built to\"), `words` is the list that takes turns at the end (default \"move.\", \"delight.\", \"last.\", \"ship.\"), and `sub` is the line below. Include any punctuation in `words`, and keep them distinct." },
    { q: "How do I change the speed and color?", a: "`interval` is the time between word changes in milliseconds (default 2000). `accent` sets the color of the rotating word (default \"#0071e3\"). The word rolls up and out of a blur with a spring." },
    { q: "What does the Replay reveal button do?", a: "It re-mounts the headline and subline so the entrance plays again: each word of `lead` and `sub` fades in from a blur, one after another. The button is part of the component, so remove it in the file if you do not want it." },
    { q: "Can I pause the rotation?", a: "There is no prop for it. The rotating word changes every `interval` milliseconds for as long as the component is mounted, looping through `words` in order." },
  ],
  "throw-wheel": [
    { q: "How do I install Throw Wheel?", a: "Run `npx shadcn@latest add @nexus-labs/throw-wheel`. It installs framer-motion. Throw Wheel is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the cards?", a: "Pass `cards` as `{ title, sub, art }`. `art` is any CSS background, such as a gradient or `url(...)`. Without it you get ten travel destinations. The drum radius and card spacing are calculated from the number of cards, and each `title` is used as a key, so keep titles unique." },
    { q: "How do I spin it?", a: "Drag sideways and let go to fling it; it coasts and snaps a card to the front. The Previous and Next buttons turn it one card. The drag area uses `touch-pan-y`, so vertical page scrolling still works on touch screens." },
    { q: "What is the blur and tilt effect?", a: "While the wheel moves, each card turns edge-on in the direction of travel and blurs more with speed. Each card has its own spring stiffness, so they straighten one by one as the wheel slows." },
    { q: "Is it usable without dragging?", a: "Yes. Previous and Next are labelled buttons, and a live region announces the front card's title. The wheel has a fixed \"Destinations carousel\" label. `autoplay` is off by default; when on it throws the wheel until someone grabs it." },
  ],
  "island-morph": [
    { q: "How do I install Island Morph?", a: "Run `npx shadcn@latest add @nexus-labs/island-morph`. It installs framer-motion. Island Morph is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Which states does it have, and how do I switch them?", a: "Four: idle, timer, call and music. The segmented control under the pill switches them, and in the call state Accept goes to timer and Decline to idle. `autoplay` (off by default) cycles them until a control is pressed." },
    { q: "Can I change the caller, song or timer?", a: "Not through props; `autoplay` is the only behavior prop. The caller \"Alex Rivera\", the song \"Night Drive\" and the demo countdown are written in the file, so edit them there. The pill sizes per state live in the `SIZES` object." },
    { q: "How does the morph work?", a: "One black element animates its width, height and border radius with a spring. Each state's content is swapped with AnimatePresence and blurs in a moment after the shape starts to move. It uses Framer Motion and no other library." },
    { q: "Which controls actually do something?", a: "Accept and Decline move between states, and the Play and Pause button toggles the music animation. Previous and Next in the music state are visual only. The pill is a `role=\"status\"` live region, so state changes are announced." },
  ],
  "stagger-menu": [
    { q: "How do I install Stagger Menu?", a: "Run `npx shadcn@latest add @nexus-labs/stagger-menu`. It is a free component and installs framer-motion." },
    { q: "How do I define the menu items?", a: "Pass `items` as `{ id, label, icon, danger?, done? }`. `icon` is any React node, `danger` makes the row red and places it after a divider, and `done` is the text the button shows after the pick (it falls back to `label`)." },
    { q: "How do I run an action when something is picked?", a: "Pass `onSelect`; it receives the item `id` and the menu closes. The component copies or downloads nothing itself, so do that in your handler. Because it is a function prop, the page that passes it must be a client component." },
    { q: "What keyboard support does it have?", a: "The button has `aria-haspopup=\"menu\"` and `aria-expanded`, and items are `menuitem` buttons. With focus inside the open menu, the up and down arrows move through items and wrap around. Escape closes it, as does clicking outside." },
    { q: "Can I change the button label or demo it automatically?", a: "`label` sets the button text (default \"Share\"). `autoplay` is off by default; when on, the menu opens and browses itself until someone interacts. Items arrive staggered, and a highlight glides between rows." },
  ],
  "venom-button": [
    { q: "How do I install the Venom Button?", a: "Run `npx shadcn@latest add @nexus-labs/venom-button`. It installs framer-motion; the goo is drawn with a WebGL shader and a 2D canvas, so no extra graphics library is needed." },
    { q: "How do I change how far the goo reaches for the cursor?", a: "`sense` (default 290) is the distance in px at which it notices the pointer, `reach` (default 140) is where the strands lunge and grab the glove fingers, and `release` (default 215) is where they snap. Keep `release` above `reach`; `strands` (default 7, range 2 to 7) sets how many thick strands there are." },
    { q: "Is the Venom Button WebGL or CSS, and what if WebGL is unavailable?", a: "The black goo surface is one WebGL fragment shader, with the strands simulated as verlet ropes and the glove cursor drawn on a separate 2D canvas. If WebGL is missing or the shader does not build, the button paints a plain glossy pill instead." },
    { q: "Is it a real button, and does it respect reduced motion?", a: "Yes. It renders a native `button` that is focusable, shows a focus ring and fires `onClick`. With prefers-reduced-motion on, it stays a still pill with the system cursor and the `autoplay` ghost glove never runs." },
  ],
  "dynamic-island": [
    { q: "How do I install the Dynamic Island component?", a: "Run `npx shadcn@latest add @nexus-labs/dynamic-island`. It installs framer-motion, and the component is a client component (\"use client\"). It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I control which activity the island shows?", a: "Pass `state` (\"idle\", \"timer\", \"music\" or \"call\") with `onStateChange` to control it yourself, or use `defaultState` (default \"timer\") to let it manage itself. `cycle` steps through `states` every N ms when uncontrolled, and `autoplay` morphs through them and opens each one." },
    { q: "What can I customize in the timer, music and call views?", a: "`timerSeconds` sets the countdown length (default 300) and it really ticks, `accent` sets the timer and music-bar color (default `#ff9f0a`), `track` takes `{ title, artist }`, and `caller` sets the name in the call view (default \"Ava Lin\")." },
    { q: "How is the morph animated, and is it keyboard accessible?", a: "It is a Framer Motion div whose width and height animate on separate springs, the width faster than the height, so the pill squashes into each new shape. The compact pill is a button with an `aria-label`, Escape or a tap outside closes the expanded controls, and with reduced motion the size changes are instant." },
  ],
  "emoji-reactions": [
    { q: "How do I install Emoji Reactions?", a: "Run `npx shadcn@latest add @nexus-labs/emoji-reactions`. It installs framer-motion and lucide-react, and the same install includes the `SparkReactions` variant. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the starting reactions and the picker emojis?", a: "Pass `reactions` as `{ emoji, count, reacted? }[]` for the starting row (default is rocket 3 and fire 2), and `emojis` for the picker options. `message` sets the bubble text, or pass `null` to show only the reactions, and `onChange` receives the updated list." },
    { q: "How do the counts animate when someone reacts?", a: "Each chip pops when you add a reaction and its count rolls digit by digit, built with Framer Motion, with a layout animation when a new chip joins the row. Clicking a chip toggles your own reaction, and `accent` (default `#5b8def`) colors the ring on reactions you added." },
    { q: "Is the picker keyboard accessible?", a: "Yes. The add button opens the picker with Enter, Space or ArrowDown and moves focus to the first emoji, Escape closes it and returns focus to the button, and chips use `aria-pressed` with a label that includes the count. With reduced motion on, the picker fades instead of scaling in and the digits fade instead of rolling." },
  ],
  "morph-cursor": [
    { q: "What is the Morph Cursor, and is it a site-wide custom cursor?", a: "It is a self-contained panel, not a global cursor. Inside it a soft dot melts into the shape of whatever you hover (icon button, pill, card), sits behind it as a highlight while the element leans toward the pointer, and becomes a caret over the text field. The system cursor is hidden only inside the panel." },
    { q: "How do I install it and what does it depend on?", a: "Run `npx shadcn@latest add @nexus-labs/morph-cursor`. It installs framer-motion; the cursor is an absolutely positioned div whose size and radius are animated with Framer Motion springs, with no canvas. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I change the contents of the panel?", a: "Pass `icons` (`{ id, label, path }` with a 24 by 24 SVG path), `buttonLabel`, `inputLabel`, `defaultInputValue` and `cards` (`{ id, label, gradient }`). `onAction` receives an icon id, \"button\" for the pill, or a card id, and `accent` (default `#0071e3`) colors the caret and focus rings." },
    { q: "Does it work with the keyboard?", a: "Yes. The targets are real buttons and an input with accessible names, and the highlight jumps to whichever one receives keyboard focus (focus-visible) and shows a focus ring. The component does not check prefers-reduced-motion." },
  ],
  "lanyard-badge": [
    { q: "How do I install the Lanyard Badge?", a: "Run `npx shadcn@latest add @nexus-labs/lanyard-badge`. It installs framer-motion; there is no physics library, the swing is a small simulation written in the component. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I change the name, role and colors on the badge?", a: "Use `name` (default \"Alex Rivera\", also used for the avatar initials), `role`, `event` (default \"Motion Summit\"), `tag` for the bottom band text (default \"Speaker\") and `strap` (default `#0071e3`) for the strap, band and avatar color. The year printed after the event name is fixed at 2026 in the source, so edit the file to change it." },
    { q: "How does the swinging physics work?", a: "A requestAnimationFrame loop moves the badge as a damped pendulum on a fixed-length strap that stretches a little while you drag, and writes the result into Framer Motion values. The strap is an SVG path that sags as the badge moves, and the badge twists with `rotateY` based on its sideways speed." },
    { q: "Can I use it with the keyboard?", a: "Yes. The badge is focusable with a visible focus ring, ArrowLeft and ArrowRight flick it sideways, and Enter or Space toss it up. `autoplay` (default false) nudges it every few seconds until someone touches it." },
  ],
  "wallet-stack": [
    { q: "How do I install the Wallet Stack?", a: "Run `npx shadcn@latest add @nexus-labs/wallet-stack`. It installs framer-motion, and the component is a client component (\"use client\"). It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I add my own cards?", a: "Pass `cards` as `{ id, name, last, bg, ink, brand, expires? }[]`, ordered from back to front, where `bg` is any CSS background such as a gradient and `last` is the last four digits. About four cards fit best, and `expires` defaults to \"08/28\"." },
    { q: "How do I know which card the user picked?", a: "`onSelect` is called with the card `id` when it slides out and with `null` when it is put back. `label` (default \"Wallet\") is stamped on the wallet, and `hint` (default \"Pick a card.\") is the caption under it, which an empty string hides." },
    { q: "How is the card flip built, and is it accessible?", a: "Each card is a Framer Motion button with `perspective` on the container and a spring on `rotateY`, with `backface-visibility` hidden on both faces, so it is pure CSS 3D with no canvas. Cards are real buttons with `aria-pressed` and a label like \"Name card ending 1234\", so Tab and Enter work." },
  ],
  "animated-icons": [
    { q: "How do I install Animated Icons?", a: "Run `npx shadcn@latest add @nexus-labs/animated-icons`. It installs framer-motion, and every icon is an inline SVG with no icon font or image files. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I use a single icon instead of the grid?", a: "Import `MenuIcon`, `PlayIcon`, `HeartIcon`, `BellIcon`, `ThemeIcon`, `BookmarkIcon`, `VolumeIcon` or `LockIcon` and pass `on` to set its state. `size` is in px (default 26), and `HeartIcon` also needs `burst`, a number you increase each time you want a new burst." },
    { q: "How do I change the animation speed and tile size?", a: "`speed` runs from 0.25 to 4 with a default of 1, and it works on every icon and on the `AnimatedIcons` grid. The grid also takes `iconSize` (default 26, 14 to 48), `tileSize` (default 72, 48 to 96) and `tileRadius` (default 20)." },
    { q: "Are the icons accessible?", a: "In the grid, each tile is a button with `aria-pressed` and a text label, and the SVGs are marked `aria-hidden`. If you use an icon on its own, put it inside your own button and give that button the accessible name. The component does not check prefers-reduced-motion." },
  ],
  "pressure-text": [
    { q: "How do I install Pressure Text?", a: "Run `npx shadcn@latest add @nexus-labs/pressure-text`. It installs framer-motion, and the effect is plain DOM with Framer Motion springs, no canvas. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Does it need a variable font?", a: "Yes, to see the weight change. Each letter's `font-variation-settings` `wght` axis moves between 250 and 900 as the pointer gets close, so the font needs a weight axis in that range. The component does not load a font itself, it uses whatever font the surrounding page sets." },
    { q: "How do I change the headline, colour and size of the bulge?", a: "Set `text` (default \"Feel every word\"), `accent` (default `#0071e3`) for the color letters take near the pointer, and `spread` for the share of the word's width that swells (default about 0.18). `hint` sets the caption under it, and an empty string hides it." },
    { q: "How is it handled for screen readers and reduced motion?", a: "The real text is in a visually hidden span and the per-letter copy is `aria-hidden`, so screen readers read the headline once. With prefers-reduced-motion on, the `autoplay` sweep does not run, though hovering still moves the bulge." },
  ],
  "liquid-gauge": [
    { q: "How do I install the Liquid Gauge?", a: "Run `npx shadcn@latest add @nexus-labs/liquid-gauge`. It installs framer-motion and nothing else; the orb, waves and bubbles are drawn with SVG. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set the capacity, starting level and warning threshold?", a: "`total` is the capacity (default 200), `defaultUsed` is the starting amount (default 136, clamped to 0..`total`), `warnAt` is the percentage where the liquid turns orange (default 85), and `unit` is the caption label (default \"GB\"). `accent` sets the liquid color below the threshold (default `#0a84ff`)." },
    { q: "How do I connect it to real usage data?", a: "`defaultUsed` is only read on the first render, so a later change to it will not move the liquid; remount the gauge with a changing `key` or edit the source to drive it from state. The built-in Clean up (-40) and Add files (+30) buttons call `onChange` with the new amount, but only when the amount actually changes." },
    { q: "How is the liquid animated, and does it respect reduced motion?", a: "Two wave paths are rebuilt every frame with requestAnimationFrame and written straight to the SVG, while the level moves on a Framer Motion spring. With prefers-reduced-motion on, the waves stop rolling, the bubbles are not rendered and the slosh on a level change is skipped. The orb has `role=\"img\"` with a \"Storage N% used\" label, and the caption is an `aria-live` region." },
  ],
  "vinyl-player": [
    { q: "How do I install the Vinyl Player?", a: "Run `npx shadcn@latest add @nexus-labs/vinyl-player`. It installs framer-motion; the record grooves and light glint are CSS gradients, so there is no canvas or WebGL. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Does the Vinyl Player actually play audio?", a: "No. It is a visual instrument only and never makes a sound, and it exposes no playback callbacks, so real audio means editing the source to drive an audio element from its play and position state. You supply the records with `tracks`, each `{ title, artist, length, label }`, where `length` is in seconds and `label` is two CSS colors for the center label; without `tracks` it shows three sample records." },
    { q: "Which props change how the record feels?", a: "`speed` is the platter speed relative to 33⅓ rpm (default 1, clamped 0.5 to 2.5), `coast` sets how long a flung record keeps spinning (default 1, 0.25 to 4), `armStiffness` sets the tonearm spring (default 80, 20 to 300) and `gloss` scales the light glint (default 1, 0 turns it off). Because a faster record carries less audio per turn, a higher `speed` makes scrubbing cover less time per rotation." },
    { q: "How does scrubbing work, and can I use the keyboard?", a: "Dragging the record moves the playback position by exactly as much as you turn it, and releasing it while moving makes it coast. The record is a `role=\"slider\"` that takes focus, and the Left and Right arrow keys move the position by 5 seconds. Play, previous and next are labeled buttons, and with prefers-reduced-motion on, `autoplay` does not start." },
  ],
  "notification-stack": [
    { q: "How do I install the Notification Stack?", a: "Run `npx shadcn@latest add @nexus-labs/notification-stack`. It depends on framer-motion and uses no canvas; the stacking, spreading and swiping are all Framer Motion springs on list items. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Is this a toast library I can call from anywhere in my app?", a: "No. It is a self-contained component that shows four sample toasts (success, error, info and a loading one) from its own buttons, and it exports no function for pushing toasts from other code. Treat it as a design to adapt: its props are `autoplay`, `duration`, `visible`, `peek`, `gap`, `stiffness`, `direction` and `enableSound`." },
    { q: "How do I change how long toasts stay and how the stack looks?", a: "`duration` is how long a toast stays in ms (default 4200, clamped 1000 to 12000), `visible` is how many show while the stack is folded (default 3, 1 to 5), `peek` is how many px of each toast behind the front one shows (default 13) and `gap` is the spacing when spread out (default 10). `direction=\"down\"` grows the stack from the top instead of the bottom." },
    { q: "How do hover, swipe and the loading toast behave?", a: "Hovering the stack spreads it out and pauses the auto-dismiss timers, which restart when the pointer leaves. Dragging a toast sideways more than 90px dismisses it, each toast also has a Dismiss button, and the list is an `aria-live=\"polite\"` region. The loading toast turns into a \"Published\" success after 1.8 seconds." },
  ],
  "ferrofluid-record": [
    { q: "How do I install the Ferrofluid Record button?", a: "Run `npx shadcn@latest add @nexus-labs/ferrofluid-record`. It installs framer-motion; the drop itself is drawn on a 2D canvas, not WebGL. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I change the number and strength of the spikes?", a: "`spikes` sets how many spikes the drop can grow (default 26, clamped 8 to 48; changing it restarts the drop), and `pull` sets how hard the magnet drags them out (default 1, 0.3 to 1.6). `size` scales the resting drop (default 1), `springiness` makes the spikes thicker and slower or twitchier (default 1) and `voice` sets how much the surface bristles while recording (default 1, 0 keeps it calm)." },
    { q: "Does it record from the microphone?", a: "No. The bristling follows a simulated voice and the component never opens the microphone. The button only toggles a recording state with a running timer and adds a short note to a list of up to three, so you add the real recording logic yourself." },
    { q: "How does the canvas simulation work, and is it accessible?", a: "Each spike is a spring simulated in fixed 60 Hz steps, and the outline is redrawn on the canvas every frame, pausing when the component is off screen or the tab is hidden. The canvas is `aria-hidden` and the control is a real button with `aria-pressed` and a \"Record a voice note\" or \"Stop recording\" label. The magnet follows the pointer only, and `autoplay` is skipped when the user prefers reduced motion." },
  ],
  "page-curl": [
    { q: "How do I install the Page Curl component?", a: "Run `npx shadcn@latest add @nexus-labs/page-curl`. It installs framer-motion, and the fold is plain DOM, so there is no canvas, WebGL or image library. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I put my own content on the page and underneath it?", a: "Pass any React nodes as `front` (the page you peel) and `back` (what is revealed), and size the page with `width` (default 400) and `height` (default 260) in px. Without them it shows a sample letter over a discount card." },
    { q: "How is the page curl effect built?", a: "The fold line is the perpendicular bisector between the bottom-right corner and your pointer. The page is cut along it with a `clip-path` polygon, and the flap is the cut-off corner mirrored across the line, shaded as the back of the paper. Because it is clip-path, the front and back can be any HTML." },
    { q: "What happens when I let go, and can I peel it with the keyboard?", a: "If the corner is dragged past about 60% of the page diagonal it peels all the way off; otherwise it springs back flat. The corner handle is a button, and pressing Enter or Space on it peels the page off, after which a \"Put it back\" button restores it. Only the bottom-right corner can be grabbed." },
  ],
  "dot-globe": [
    { q: "How do I install the Dot Globe?", a: "Run `npx shadcn@latest add @nexus-labs/dot-globe`. It installs framer-motion only; the globe is drawn on a 2D canvas with its own projection math, so it does not use three.js or WebGL. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I add my own cities and flight routes?", a: "Pass `cities` as `{ id, name, lat, lon }` objects and `routes` as pairs of city ids, for example `[[\"ber\", \"nyc\"]]`. A route that names an unknown id is skipped. The defaults are the exported `DOT_GLOBE_CITIES` and `DOT_GLOBE_ROUTES`." },
    { q: "Does it draw continents or a real map?", a: "No. The 1,600 dots sit on an even lattice over the whole sphere, so the globe has no land shapes. Only your city pins and the great-circle arcs between them carry geographic meaning, which suits a flight or office-network visual rather than a map." },
    { q: "How do I control the size and color, and how does interaction work?", a: "`size` is the square canvas size in px (default 340) and `accent` colors the arcs, pins and selected chip (default `#0071e3`). Dragging spins the globe and it coasts to a stop, and clicking a city chip springs the globe round to it. The chips are buttons with `aria-pressed`, so they give keyboard users a way to rotate it, and the canvas has `role=\"img\"` with a label naming the selected city." },
  ],
  "feedback-pill": [
    { q: "How do I install the Feedback Pill?", a: "Run `npx shadcn@latest add @nexus-labs/feedback-pill`. It installs framer-motion, and the morph from pill to form is a Framer Motion layout animation." },
    { q: "How do I send the feedback to my own backend?", a: "Pass `onSend`, which receives the message string and can return a promise. The Send button shows a spinner until the promise resolves (for at least 900 ms), then the pill shows \"Thanks, got it.\" and folds back after about 1.7 seconds. The component does not send anything over the network itself." },
    { q: "Where does it go on the page, and how do I change the text and color?", a: "It is not fixed-positioned, so wrap it in your own container such as `fixed bottom-6 right-6`. `label` sets the pill text and form title (default \"Feedback\"), `placeholder` sets the textarea hint (default \"What would make this better?\") and `accent` sets the Send button and focus color (default `#0071e3`)." },
    { q: "What keyboard shortcuts does it support?", a: "Press Cmd+Enter or Ctrl+Enter in the textarea to send and Escape to close the form. The textarea has a real `label`, Send is disabled while the text is empty, and the confirmation uses `role=\"status\"`. Interface sounds are on by default and can be turned off with `enableSound={false}`." },
  ],
  "pulse-monitor": [
    { q: "How do I install the Pulse Monitor?", a: "Run `npx shadcn@latest add @nexus-labs/pulse-monitor`. It installs framer-motion; the ECG trace is drawn on a 2D canvas and the 24 hourly range bars are regular DOM elements. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Does it show real heart-rate data?", a: "No. The beats-per-minute reading and the 24 hourly range bars are generated from the `bpm` prop (default 68) with a fixed pseudo-random seed, so a given `bpm` always gives the same day. There is no prop for feeding real samples, so change the `hourly` function in the source to use your own data." },
    { q: "How do I change the colors and the workout rate?", a: "`color` sets the trace, heart and bars at rest (default `#ff375f`) and `workoutColor` is what everything warms to during a workout (default `#ff9f0a`). Start workout raises the rate to `max(bpm + 50, 120)` and speeds up the beats." },
    { q: "Is the hourly chart keyboard accessible, and does it respect reduced motion?", a: "Yes. The range bars are a focusable `role=\"slider\"` where the arrow keys step through the hours, Home and End jump to 00:00 and 23:00, Escape clears the selection, and a screen-reader-only live region announces the range. With prefers-reduced-motion on, the heart no longer pulses and the number fades instead of sliding, but the ECG trace keeps sweeping." },
  ],
  "otp-input": [
    { q: "How do I install the OTP Input and what does it export?", a: "Run `npx shadcn@latest add @nexus-labs/otp-input`. It depends on framer-motion and exports three variants from the same folder: `OtpInput` (six boxes), `OtpAutofill` (a pretend text message with a Fill button) and `OtpLine` (underlines without boxes)." },
    { q: "How do I verify the code against my backend?", a: "Pass `verify` to `OtpInput` as a function that takes the code and returns a boolean or a promise of one; it runs once every box is filled, after a short \"Checking…\" state. By default `verify` only accepts the demo code \"482913\", so always replace it. `onVerified` fires on success and `onResend` fires when Resend code is pressed." },
    { q: "Does it support SMS code autofill and a custom length?", a: "Yes. The boxes are drawn over one real input with `autoComplete=\"one-time-code\"` and `inputMode=\"numeric\"`, which is what browsers use to offer a code from a text message, and non-digit characters are stripped. `length` sets the number of digits (default 6) and `accent` sets the focus ring, caret and success color (default `#0071e3`); `OtpAutofill` and `OtpLine` are fixed at six digits." },
    { q: "What happens on a wrong code, and how does it handle accessibility and reduced motion?", a: "A wrong code shakes the row, shows \"That code didn’t match. Try again.\" and clears the boxes, while a right code folds the boxes into a Verified pill with `role=\"status\"`. The input has a screen-reader label, \"One-time code\". `OtpAutofill` and `OtpLine` never run their autoplay demo under reduced motion (and `OtpLine` skips its shake), but the main `OtpInput` animations do not check that setting." },
  ],
  "matrix-loaders": [
    { q: "How do I install the Matrix Loaders?", a: "Run `npx shadcn@latest add @nexus-labs/matrix-loaders`. The only library it depends on is framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I use a single loader instead of the six-tile grid?", a: "Import `MatrixLoader` and pass `pattern` as \"wave\", \"ripple\", \"spiral\", \"rain\", \"halogen\" or \"checker\" (or an index from 0 to 5; the default is 0). `size` is the grid width in px (default 64) and `color` overrides the pattern's own colour." },
    { q: "How is the dot-matrix animation built?", a: "It is a 5x5 grid of ordinary DOM dots, not canvas or WebGL. Every dot runs the same Framer Motion scale and opacity pulse, and only its start delay changes by position, which is what makes the wave, ripple, spiral, rain, halogen or checker shape." },
    { q: "Is the loader accessible, and does it respect reduced motion?", a: "Each loader has `role=\"status\"` and an `aria-label` taken from `label`, which defaults to the pattern's name such as \"Thinking\". With reduced motion on, the scale pulse is replaced by a slower opacity fade, and the labels in the grid stop pulsing." },
  ],
  "glass-bubbles": [
    { q: "How do I install Glass Bubbles?", a: "Run `npx shadcn@latest add @nexus-labs/glass-bubbles`. It depends on framer-motion and no physics library. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Which props change how the bubbles move?", a: "`size` (0.6 to 1.3), `threadLength` (0.5 to 1.3), `gravity` (0.2 to 3), `drag` (0.25 to 4) and `push` (0.2 to 3) all default to 1, and values outside the range are clamped. Lower `drag` keeps them swinging longer, and `push` sets how hard the pointer shoves an orb." },
    { q: "Is this canvas, WebGL or a physics engine?", a: "None of them. A requestAnimationFrame loop runs simple Verlet pendulums with circle collisions, and Framer Motion values move the orbs, which are DOM elements styled with CSS gradients and blur. The threads are SVG paths." },
    { q: "Does it work with the keyboard and reduced motion?", a: "The stage is focusable, and the Left and Right arrow keys push every bubble sideways. With prefers-reduced-motion on, `autoplay` no longer nudges the bubbles, but pointer and arrow-key input still move them." },
  ],
  "time-scrubber": [
    { q: "How do I install Time Scrubber?", a: "Run `npx shadcn@latest add @nexus-labs/time-scrubber`. It installs framer-motion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },    { q: "How do I get and set the time in Time Scrubber?", a: "Time is a number of minutes since midnight. Use `value` with `onChange` to control it, or `defaultValue` (570, which is 9:30) to leave it uncontrolled. `onChange` receives the snapped time, and `onCommit` fires once the ruler comes to rest." },
    { q: "How do I change the step size and clock format?", a: "`interval` is the number of minutes the ruler snaps to (default 15), `format` is \"12h\" or \"24h\" (default \"12h\"), and `density` is pixels per minute on the ruler (default 1.6). `accent` sets the needle colour and `disabled` ignores input." },
    { q: "Can I use it with a keyboard or mouse wheel?", a: "Yes. The ruler is a focusable `role=\"slider\"` with a spoken time in `aria-valuetext`. Arrow keys move by one `interval`, PageUp and PageDown by 60 minutes, and Home and End jump to the start and end of the day. The wheel and trackpad move one interval per notch." },
    { q: "How is the ruler built, and what happens with reduced motion?", a: "The ticks are DOM elements moved by a Framer Motion value with inertia, with an SVG sun and moon glyph in the sky chip, so there is no canvas. With reduced motion on, the ruler snaps straight to the target time, the digits change without rolling, and the needle bounce is skipped." },
  ],
  "before-after": [
    { q: "How do I add my own images to the Before / After slider?", a: "Run `npx shadcn@latest add @nexus-labs/before-after`, then pass `before` and `after` as React nodes, usually an `<img>` with `className=\"h-full w-full object-cover\"`. The frame is a fixed 16:9 box, so `object-cover` keeps differently sized images from distorting. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I change the labels?", a: "Use `beforeLabel` and `afterLabel`, which default to \"Before\" and \"After\". Each label fades out as the handle moves close to its side of the frame." },
    { q: "How does the comparison effect work?", a: "The after layer sits underneath and the before layer sits on top, cropped with a CSS `clip-path` driven by a Framer Motion spring. It is CSS plus Framer Motion with no canvas, and you can click or drag anywhere on the image to move the handle." },
    { q: "Does it support keyboard control and reduced motion?", a: "The handle is a focusable `role=\"slider\"`, and the Left and Right arrow keys move it 5% at a time. The Before, Split and After buttons jump to 100%, 50% and 0%. The component does not read prefers-reduced-motion, so leave `autoplay` off (the default) if you need that." },
  ],
  "marble-progress": [
    { q: "How do I install Marble Progress?", a: "Run `npx shadcn@latest add @nexus-labs/marble-progress`. It installs framer-motion and matter-js, the physics engine that moves the marbles. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I set my own checklist steps?", a: "Pass `steps` as an array of `{ label, color }`, where `color` is a 6-digit hex used for the checkbox and its marble. Labels are used as React keys, so keep them unique. Ticked state lives inside the component and there is no `onChange` or controlled prop, so edit the source if you need to save progress." },
    { q: "Which props change the marble physics?", a: "`marbleSize` is the radius in px (default 9, clamped 6 to 11), `bounciness` defaults to 0.45 (0.05 to 0.85) and `gravity` defaults to 1 (0.4 to 1.6). `glowColor` (default `#30d158`) sets the light that fills the jar when every step is done." },
    { q: "Is it canvas or WebGL, and is the checklist accessible?", a: "The ramps, jar and marbles are drawn on a 2D canvas with Matter.js, and the canvas is hidden from screen readers. Each step is a button with `role=\"checkbox\"` and `aria-checked`, and the \"of\" counter is a polite live region. With reduced motion on, only `autoplay` is turned off, so marbles still drop when someone ticks a step." },
  ],
  "morphing-dialog": [
    { q: "How does the dialog morph out of the button?", a: "The button and the dialog share a Framer Motion `layoutId` inside a `LayoutGroup`, so the dialog grows from the button and shrinks back into it on close. It uses a spring with stiffness 380 and damping 32, and there is no canvas or WebGL." },
    { q: "How do I change the project name, page count and share link?", a: "Install with `npx shadcn@latest add @nexus-labs/morphing-dialog`, then pass `projectName` (default \"orbitly-site\"), `pageCount` (14) and `shareBase` (\"nexus.app/p\"). The Copy button puts `https://` plus `shareBase`, a slash and `projectName` on the clipboard. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How does the delete confirmation work?", a: "The \"Delete forever\" button stays disabled until the input exactly matches `projectName`. `onDelete` is called when the delete is confirmed, and `onRestore` when the Restore button is pressed afterwards." },
    { q: "Is it accessible, and does it respect reduced motion?", a: "Share is a `role=\"dialog\"` and Delete is a `role=\"alertdialog\"`, both with `aria-modal`. Escape or a click on the backdrop closes them, Tab stays inside the open dialog, the page behind is `inert`, and focus returns to the button that opened it. With reduced motion on, the morph becomes a 0.15 second fade and `autoplay` never runs." },
  ],
  "hold-to-confirm": [
    { q: "How do I install Hold to Confirm and run code when it completes?", a: "Run `npx shadcn@latest add @nexus-labs/hold-to-confirm`, which depends on framer-motion. `onConfirm` is called once the hold completes, and `onUndo` is called if Undo is pressed on the toast before its 5 second countdown ends. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How long do you have to hold, and what can I relabel?", a: "`holdMs` is the hold time in milliseconds (default 1500). `label` defaults to \"Hold to Delete\", `holdingLabel` to \"Keep holding…\" and `doneLabel` to \"Project deleted\", and `color` (default `#ff3b30`) sets the fill and text colour." },
    { q: "Does it work with the keyboard and on touch screens?", a: "Yes. Holding Space or Enter fills the button just like holding the pointer, and releasing early or moving the pointer off the button springs the fill back without calling `onConfirm`. The button has `touch-none` and its context menu is blocked, so a long press on mobile does not open a menu." },
    { q: "How is the hold effect built, and does it respect reduced motion?", a: "A Framer Motion value animates linearly from 0 to 1 over `holdMs` and drives a `scaleX` fill and a `clip-path` that reveals the \"Keep holding\" label. The tick and burst are SVG and DOM, with no canvas. The component does not check prefers-reduced-motion." },
  ],
  "tilt-pass": [
    { q: "How do I install the Tilt Pass component?", a: "Run `npx shadcn@latest add @nexus-labs/tilt-pass`. It installs framer-motion; there is no canvas or WebGL, only CSS 3D transforms driven by Framer Motion springs. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Which props change the text on the pass?", a: "`title` is the pass name (default \"Founders Pass\"), `name` is the holder (default \"Alex Rivera\") and `number` is the membership number (default \"No. 0042\"). The holder name and number appear on both the front and the back." },
    { q: "How does the tilt, glare and shadow effect work?", a: "The pointer position over the card feeds two springs that set `rotateX` and `rotateY` (up to 12 and 16 degrees respectively), move a radial-gradient glare, shift a holographic sheen and slide the drop shadow the opposite way. Set `autoplay` to make it float by itself while the pointer is away." },
    { q: "How do I flip the pass, and can I put a real QR code on the back?", a: "Click it, or focus it and press Enter or Space; it is a `role=\"button\"` element with an aria-label that switches between showing the front and the back. The back is a decorative 8 by 8 grid of squares rather than a real QR code, so replace that block in the source with your own QR component." },
  ],
  "metal-orbs": [
    { q: "How do I install Metal Orbs?", a: "Run `npx shadcn@latest add @nexus-labs/metal-orbs`. It installs framer-motion, which is only used for the sliding highlight on the joined, apart and orbit switcher. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Does Metal Orbs use WebGL or a shader?", a: "No. Each frame it computes a metaball field on a half-resolution buffer, derives a surface normal from the field and shades it with a fake chrome reflection, then draws it to a 2D canvas with requestAnimationFrame. Because this runs on the CPU, a larger `width` and `height` costs more per frame." },
    { q: "How do I change the size or the starting motion?", a: "Pass `width` and `height` in px (defaults 440 and 280). It starts in the \"apart\" mode, and `autoplay` cycles through joined, orbit and apart every 2.6 seconds until someone clicks the canvas or a mode button." },
    { q: "Can visitors interact with the orbs?", a: "Yes. Pressing and dragging on the canvas pulls the left, blue-tinted orb around, and the right one bulges toward it when they get close; the three mode buttons are real buttons with `aria-pressed`. The canvas has an `aria-label` describing the two orbs, and the floor shadows adjust when the page has the `dark` class on the html element." },
  ],
  "bubble-cluster": [
    { q: "How do I install Bubble Cluster?", a: "Run `npx shadcn@latest add @nexus-labs/bubble-cluster`. It installs framer-motion; the bubbles are plain DOM elements and there is no canvas or WebGL. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I pass my own contacts and groups?", a: "Give `people` as `{ id, name, hue }` objects and `groups` as an object of group name to `{ personId: closeness }`, with closeness from 1 to 5. A bigger number gives a bigger bubble, and anyone left out of a group shrinks away when that group is selected." },
    { q: "Which props tune the look and the motion?", a: "`gap` is the space between bubbles in px (default 5, range 0 to 24), `sizeContrast` is how much closeness changes size (default 1, range 0 to 2), `bounce` is how springy the movement is (default 1, range 0.5 to 2.5) and `liquid` is the strength of the backdrop (default 1, 0 hides it). `autoplay` steps through the groups every 2.6 seconds until someone presses the cluster or the switcher." },
    { q: "How is the gooey backdrop made, and is it accessible?", a: "The positions come from a small circle-packing function and the backdrop is blurred circles passed through an SVG `feGaussianBlur` and `feColorMatrix` filter, all animated with Framer Motion springs. Bubbles are a `role=\"list\"` with labels like \"Mom, 5 of 5 close\" and the group switcher is made of buttons with `aria-pressed`, but the bubbles themselves are not focusable." },
  ],
  "upload-dropzone": [
    { q: "How do I install the Upload Dropzone?", a: "Run `npx shadcn@latest add @nexus-labs/upload-dropzone`. It installs framer-motion and includes four exports: `UploadDropzone`, `AvatarUpload`, `UploadQueue` and `EmptyTable`. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I send files to my own server?", a: "Pass `onUpload`, a function that receives the `File` and a `setProgress` callback (0 to 1) and returns a promise; resolve it when the upload finishes or reject it to mark the row as failed. Without `onUpload` the uploads are simulated, so nothing leaves the browser." },
    { q: "How do I limit file types and size?", a: "Use `accept` with the same syntax as the input attribute (for example \"image/*,.pdf\"), `maxSize` in bytes (default 5242880, which is 5 MB) and `multiple` (default true). Files that fail show an error such as \"Over 5 MB\" or \"Not supported\" in the list and shake the zone, while `onFiles` is called only with the accepted ones." },
    { q: "Does it work with the keyboard and reduced motion?", a: "Yes. The drop zone is a focusable `role=\"button\"` that opens the file picker on Enter or Space, each row has a remove button, and results are announced through an `aria-live` region. With reduced motion on, the sheets do not fan out, the zone does not scale or shake and the list rows only fade." },
  ],
  "tape-shelf": [
    { q: "How do I install Tape Shelf?", a: "Run `npx shadcn@latest add @nexus-labs/tape-shelf`. It installs framer-motion; the 3D shelf is made with CSS transforms and the reels are small SVGs. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I show my own tapes and react to a pick?", a: "Pass `tapes` as `{ title, artist, color, ink }` objects, where `color` is the spine and label colour and `ink` is the text colour on them. `onPick` is called with the tape index when someone picks one and with `null` when it goes back." },
    { q: "Which props change the shelf?", a: "`size` scales the cases (default 1, range 0.8 to 1.3), `spacing` is the gap in px (default 6), `tilt` is how far the shelf turns away (default 1, 0 shows the spines straight on), `lift` is how far a hovered case rises (default 1) and `snap` is the spring speed (default 1). `autoplay` pulls out the 3rd, 6th and 1st tapes in turn every 1.8 seconds until someone touches the shelf." },
    { q: "Can I use it with a keyboard, and what happens with reduced motion?", a: "Each case is a button with `aria-pressed` and a label like \"Title by Artist\", focusing one lifts it, Enter or Space picks it and Escape puts the picked tape back. With reduced motion on, the reels stop turning; the swing and spring movements still play." },
  ],
  "web-sling-button": [
    { q: "How do I install the Web Sling Button?", a: "Run `npx shadcn@latest add @nexus-labs/web-sling-button`. The catalog lists no npm dependencies for it, because the silk is drawn with WebGL on a canvas overlay and the meter and button are plain DOM." },
    { q: "How do I handle clicks on the button?", a: "Pass `onClick`; it fires only when the button itself is clicked. A click or drag anywhere else on the stage shoots or pulls a web instead, and the stage has `touch-none` so dragging works on touch screens." },
    { q: "Which props control the stage and the silk?", a: "`label` is the button text (default \"Get started\"), `height` is the stage height in px (default 460) and `snapAt` is how far a strand can stretch, as a multiple of its length, before it snaps (default 2.3). Lower `snapAt` for lines that snap sooner; `autoplay` runs a ghost that shoots, pulls and snaps lines until a real pointer arrives." },
    { q: "What happens with reduced motion, sound or no WebGL?", a: "With `prefers-reduced-motion` on, no webs are fired and the stage stays still, but the button is a real `button` and still works with the keyboard. Sounds are synthesised with the Web Audio API and follow the site-wide sound switch; pass `enableSound={false}` to keep it silent. The silk is drawn only where WebGL is available." },
  ],
  "ghost-autocomplete": [
    { q: "How do I install Ghost Autocomplete?", a: "Run `npx shadcn@latest add @nexus-labs/ghost-autocomplete`. It installs framer-motion; the component is a real `textarea` with a mirrored text layer on top that draws the grey suggestion. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "Does it call an AI model for the suggestions?", a: "No. Suggestions come from the `rules` prop, a list of `[regex, suggestion]` pairs: when the text ends with a match, the suggestion appears after a 650 ms pause. Use patterns that end in `$` and have no `g` flag, and to connect a real model, change the `suggest` function in the source." },
    { q: "How do I accept or dismiss a suggestion?", a: "Press Tab to accept, which inks the text in left to right and calls `onAccept` with the suggestion, or Escape to dismiss it. Tab only does this while a suggestion is showing, so keyboard focus is never trapped, and typing the same letters makes the ghost shrink as you follow it." },
    { q: "Why does passing rules from a server page fail, and how is it made accessible?", a: "Regular expressions cannot be handed from a server component to a client component, so define `rules` in a file that starts with \"use client\". The textarea has an aria-label, and each suggestion is announced through a polite live region; with reduced motion on, the ink-in and drop-away animations are skipped and autoplay does not run." },
  ],
  "code-snippet": [
    { q: "How do I install Code Snippet?", a: "Run `npx shadcn@latest add @nexus-labs/code-snippet`. It installs framer-motion; the syntax highlighting is a small built-in tokenizer, so there is no Prism or Highlight.js dependency. It is a Pro component, so it needs a Pro plan and an API key; key setup is on the CLI docs page (/docs/cli)." },
    { q: "How do I show my own code in it?", a: "There is no `code` prop. The component ships five sample snippets (JS, TS, Python, Bash and JSON) in a `SNIPPETS` object at the top of the file, so edit that object to show your own code. Highlighting covers only those five languages, with comments, strings, numbers, keywords, function calls and JSON keys coloured." },
    { q: "Which props change the look?", a: "`initial` picks the first language (\"js\" by default), `theme` is \"dark\" or \"light\" (default \"dark\"), `lineNumbers` defaults to true and `controls` (default true) shows the row of chips for language, theme and line numbers. Set `autoplay` to tour the languages every few seconds until someone touches it." },
    { q: "How does the Copy button work?", a: "It writes the currently shown snippet to the clipboard with `navigator.clipboard.writeText`, then the label morphs into a tick for about 1.6 seconds. The Copy button and the language switch in the header are real buttons with aria-labels, so both work with the keyboard." },
  ],
};
